    "contribution": "贡献是把检索、局部匹配、异常过滤与高程约束整合为可运行的三维定位流程。系统仍依赖预建且及时的卫星与高程数据库，地貌变化和影像差异会影响定位；目前两处场景及所用硬件的结果不足以保证跨季节或任意地区的实时可靠性。\n---\nDOI: 10.1016/j.neunet.2026.109679",
