    "summary": "本文提出 D3-KD，用漂移校正的扩散生成器扩充目标域乳腺超声数据，在无法访问教师模型源域训练数据时，提升轻量学生网络的跨域病灶分割效果。",
    "question": "临床环境常因隐私与跨机构限制而不能保留教师模型的源域数据，学生只能在分布不同的目标域上学习；此时直接蒸馏会因教师决策边界与目标样本覆盖不足而收益有限。乳腺超声又具有散斑噪声重、对比度低和边界模糊的特点，因而需要既能补足数据覆盖、又可部署于资源受限场景的分割方案。",
    "method": "D3-KD 先从理论上把蒸馏收益与源、目标分布支持集的重叠联系起来，再以 Drift-Corrected Efficient Diffusion（DCED）生成与病灶掩码一致的目标域扩增样本。DCED 用 DANR 校正分类器无关引导下逐步累积的噪声漂移，并以 Shifted-Start Sampling 跳过低信噪比早期步；学生同时接受分割监督、教师 logits 一致性、特征关系和原型关系蒸馏。",
    "experiments": "作者以 BUS-BRA 预训练教师，并在 BUS-UCLM 等异质乳腺超声设置评估多种教师—学生组合。最具挑战的 BUSSAM→ResUNetSE 设置中，D3-KD 报告 Dice 91.63%、HD95 为 2.05；在“真实数据 + DCED”比较中，标准 KD 的 Dice 从 81.25% 升至 88.30%，完整 D3-KD 为 91.63%。生成数据相对源域的 MMD 从 1.2632 降至 1.0745，FID 从 51.91 降至 22.56。",
    "contribution": "- 将源域未知蒸馏的分布覆盖问题、扩散式数据桥接和关系蒸馏整合为一个医学分割框架。\n- DANR 与移位起始采样针对扩散采样漂移和效率给出专门设计，并通过消融验证各模块作用。\n- 局限：结果依赖于生成样本能覆盖与源域相关的缺失区域；实验集中于乳腺超声及特定数据划分，跨设备、跨疾病和真实临床部署的泛化性仍需验证。\n---\nDOI: 10.1016/j.neunet.2026.109633",
