    "method": "作者以 Docker 化 Tor 客户端和多种混淆传输采集 PCAP，抽取包大小、方向、相对时间与到达间隔，并用时间阈值将流量划为 traces。判别器先以一维 CNN 压缩包向量，再用两层双向 LSTM 依次学习流级和 trace 级表示；类别条件 GAN 生成少数类特征，判别器训练时额外区分合成类、测试时输出真实流量类别。",
    "experiments": "在近均衡数据上，模型的 Macro-F1 点估计为 0.89，与表中最高值持平。控制失衡实验中，训练集 Tor 类被移除 90%，完整管线的 Tor recall 为 0.92、Tor F1 为 0.88、Macro-Recall 为 0.92、Macro-F1 为 0.91；保持 CNN/BiLSTM 主干的消融中，加入生成器的 Tor recall/F1 分别为 0.92/0.88，高于无生成器的 0.69/0.79 和加权损失的 0.74/0.82。",
    "contribution": "- 构建覆盖五种常见混淆传输、普通 Tor 与非 Tor 加密流量的采集与层次分类流程。\n- 将类别条件 GAN 用作少数类特征扩增，并用保持同一主干的消融单独检验生成器作用。\n- 局限：端到端比较使用了不同分类器主干，微小分差只能作描述性解释；划分为 trace 级，仍可能保留同一采集条件的相关性，更多失衡模式、跨会话验证和背景流量注入尚待评估。\n---\nDOI: 10.1016/j.cose.2026.105167",
