    "summary": "论文形式化图反事实解释的最小化问题并证明其 NP-hard，提出与生成器解耦的 Local Bounded Search（LBS），在保持预测翻转有效的同时缩小图结构和属性修改。",
    "question": "图模型的反事实解释应尽可能接近原图，同时改变模型预测。现有方法多先生成一个有效反事实再粗略精简，但“最小化”缺少统一定义，随机换边启发式又依赖特定生成器，限制了可解释性和复用性。",
    "method": "作者定义 Graph Counterfactual minimization 优化问题并给出 NP-hard 证明，随后采用 generate-and-minimize 两阶段框架。LBS 在受限预算内搜索边添加、删除、交换和属性扰动的局部邻域，以模型无关方式降低编辑距离并保留反事实有效性；配套的 DCEM 用于控制生成阶段的 oracle 调用复杂度。",
    "experiments": "在分子、生物医学和社交网络等九个合成及真实数据集上，LBS 相对初始反事实最多将结构编辑距离降低 98%，并稳定优于现有精简启发式。消融显示，受限搜索预算、属性感知扰动、互补邻域算子和先检查小删除的策略顺序都对最小化效果关键。",
    "contribution": "- 首次系统形式化 GC-min 并给出复杂度结论。\n- 提供可附加在任意有效反事实生成器后的模型无关精简算法。\n- 局限：启发式无法保证全局最优，且解释的领域可行性仍需由应用约束定义；更丰富图编辑空间会提高搜索成本。\n---\nDOI: 10.1007/s10994-026-07157-0",
