    "summary": "LogSqueeze 是面向 APT 实时分析的日志压缩系统，以时空特征和多阶段溯源图保留攻击关键线索，并动态调节压缩策略以兼顾吞吐与检测准确性。",
    "question": "APT 的隐蔽性和持续演化要求安全系统持续保存进程、文件与网络行为，但高速日志流使实时检测和取证面临存储、带宽与计算压力。常规压缩往往难以适应不同场景，也可能丢失攻击因果链上的关键信息。",
    "method": "系统先在滑动窗口内做时空聚合，并结合差分编码和字典编码压缩日志；随后通过逐层演化的 provenance graph 识别和保留高价值事件。它把压缩引擎与异常检测模块解耦，并依据流量与图结构状态调整压缩参数，从而在减少数据量时维持攻击链可追踪性。",
    "experiments": "论文在 DARPA TC 和实验网络靶场等数据上评估实时场景，报告检测准确率为 98.2%，实时压缩率较比较方案提高超过 30%。文中还给出单处理单元约 52K events/s 的吞吐估计，并指出压缩可将 LSTM 所需训练语料最多缩小 12.6 倍。",
    "contribution": "- 将在线日志压缩、溯源图演化和自适应参数调整整合为统一的 APT 防御管线。\n- 以关键事件保留而非单纯字节缩减为优化目标，支持后续检测与取证。\n- 局限：评测主要来自可控数据集和靶场，异构生产网络的长期稳定性仍待现场试验；异常模块仍依赖足够的干净历史数据。\n---\nDOI: 10.1016/j.cose.2026.105169",
