    "summary": "本文提出属性引导的人脸模板反演方法 AFTI，通过显式约束眼、鼻、口等语义属性，提高从泄露模板重建人脸时的 Type-II 攻击成功率和跨模型迁移能力。",
    "question": "人脸识别模板若被泄露，攻击者可能利用特征向量恢复可用于冒充的面部图像。现有反演通常只优化像素或感知损失，在未知目标模型的 Type-II 场景以及跨模型攻击中泛化不足，原因在于模板到图像的映射存在较大的语义歧义。",
    "method": "AFTI 把面部局部属性作为可解释的语义约束，设计属性损失以限制生成图像与目标模板对应的眼、鼻和口部特征。该损失分别嵌入轻量 UCNet 与生成式 M-StyleGAN3 两类反演框架，使网络同时追求模板匹配、视觉质量和属性一致性。",
    "experiments": "实验比较 UCNet、M-StyleGAN3 及其属性引导版本，在 Type-II 攻击、跨模型泛化和多项重建/攻击指标上检验效果。作者报告 AFTI 提升了 True Accept Rate、FAMSE、DFS 与攻击精度，并在训练模型之外的识别模型上保持更好的迁移表现；UCNet 训练为 300 epoch，属性引导 M-StyleGAN3 为 20 epoch。",
    "contribution": "- 把细粒度面部属性引入模板反演，缓解单纯视觉损失的语义不确定性。\n- 证明同一属性损失可作用于轻量网络和 StyleGAN 型生成器，并改善跨模型攻击。\n- 局限：人眼主观相似度和精细局部控制仍不充分；该类研究揭示的是生物特征模板保护风险，防御侧仍需结合模板保护与访问控制。\n---\nDOI: 10.1016/j.neunet.2026.109620",
