    "summary": "本文设计守恒质量的时空自适应 PINN，通过按能量衰减切分时间、按残差加密空间采样，并在损失中加入质量约束，求解强非线性和奇异 Cahn–Hilliard 方程。",
    "question": "Cahn–Hilliard 相场方程含高阶导数、强非线性，Flory–Huggins 势还会引入奇异性；长时演化中的状态变化使固定时间划分不合适。标准 PINN 又不能严格保持质量守恒，导致物理量随训练漂移。",
    "method": "方法以能量下降速率自适应划分时间子区间，并在每个子区间内训练 PINN；空间上将高残差点补入训练集。损失函数额外约束总质量，对奇异势问题把网络输出映射到 [-0.9, 0.9]，以避免对数项附近的梯度爆炸。",
    "experiments": "数值实验覆盖不同 bulk potential 的二维方程、具有奇异势的三维问题及方程组。对 Ginzburg–Landau 势，最终阈值设置在长期误差和质量误差之间最平衡；对更棘手的 Flory–Huggins 势，自适应划分和约束带来的误差改善更明显，并保持质量守恒。",
    "contribution": "- 将时间分段、空间残差采样与守恒约束统一用于相场 PINN。\n- 针对奇异对数势加入有界输出映射，改善训练可行性。\n- 局限：能量阈值选择仍带有启发性；更高维、长时且复杂边界条件下的计算成本和理论误差界仍需研究。\n---\nDOI: 10.1016/j.neunet.2026.109634",
