    "summary": "本文把欧盟 AI Act 与 Cyber Resilience Act 中面向网络安全的义务拆解为可审计控制项，并针对 LLM 自主代理给出“法律义务—技术控制—合规证据”的映射矩阵。",
    "question": "两部法规提出风险管理、韧性、事件报告等结果导向义务，却很少说明代理系统应采用何种工程控制。对于同时带有工具调用、记忆和编排能力的 LLM agent，提供方、审计人员和监管机构缺少一致的技术基线。",
    "method": "论文以教义分析拆分 AI Act 第 9–15、53、55、72–73 条及 CRA 第 13–14 条与附录 I 的网络安全义务。作者以提示注入、工具投毒、记忆/RAG 投毒、过度代理、隐私攻击和供应链破坏构建威胁模型，再将每个义务原子映射至控制目录与 agent 安全研究中的具体控制，并指定应保留的验证证据。",
    "experiments": "该文是规范与技术控制的分析研究，不以分类精度等数值实验为主。其结果是覆盖合规评估的 obligation-to-control matrix：CRA 的推定合规机制可用于落实 AI Act 的安全要求，同时也指出现有法规和待发布协调标准仍未充分覆盖自主代理行为。",
    "contribution": "- 建立从欧盟法规条款到 LLM agent 技术控制和审计证据的可追溯链条。\n- 将 agent 特有攻击面纳入 AI Act 与 CRA 的联合合规讨论。\n- 局限：法律解释与标准化进程会随实施细则变化；控制矩阵仍需在具体产品、司法辖区和监管实践中检验其可操作性。\n---\nDOI: 10.1007/s10207-026-01336-9",
