    "method": "框架冻结全局主干，在其上插入模块化 LoRA-MoE 适配器，借由专家路由隔离可编辑知识。CLIP 提供跨模态高层语义监督，作为正则项约束遗忘前后保留数据表示；训练目标同时考虑保留准确率、遗忘准确率、成员推断风险与通信开销。",
