    "contribution": "- 将参数高效适配、专家分工和语义正则组合为联邦遗忘的细粒度编辑机制。\n- 同时报告遗忘、效用、成员推断与通信成本，体现实际权衡。\n- 局限：专家路由在大规模异构客户端下可能不稳定；验证集中于图像分类，向文本、生成模型及更强攻击者的扩展尚待研究。\n---\nDOI: 10.1016/j.neunet.2026.109632",
