    "summary": "本文提出 Self-Action Distribution System（SADS），先以无需梯度的稳定性分析评估网络结构，再结合低空间复杂度记忆网络，试图在训练前降低试错成本并提升符号任务表现。",
    "question": "神经网络设计通常依赖“建模—训练—看损失—再修改”的循环，缺少事前稳定性依据，可能造成无效训练和额外算力消耗。作者认为记忆结构也常受显存约束，因此希望把稳定性诊断与更节省空间的记忆机制连接起来。",
    "method": "论文构造基于广义上界与 Lipschitz 条件的稳定性评价方法，不依赖反向梯度，供训练前筛查结构风险。在此基础上实现记忆网络，并以改进递归信息表示模块组成 SADS 与带记忆版本 SADSMem；设计强调用较紧凑的状态表示承载符号信息。",
    "experiments": "作者在 LRA、IMDB、QQP、SNLI、MNLI 和 Proplogic 等任务上比较多种网络。按最优结果差距、差距方差和平均准确率汇总，RIR、SADS 与 SADSMem 在文中的三项综合指标上占优；显存和时间分析同时显示，使用两个 ERIR 组件的 SADS/SADSMem 比单个 ERIR 有更高资源开销。",
    "contribution": "- 提供不求梯度的网络稳定性评价视角，并将其用于训练前的结构筛选。\n- 将低空间记忆网络与稳定性设计结合，提出 SADS 系列算法并给出多任务比较。\n- 局限：稳定性指标与实际下游性能之间的普适对应关系仍需更广泛架构验证；完整 SADS 的显存与运行时间代价也限制了其资源受限部署。\n---\nDOI: 10.1016/j.neunet.2026.109635",
