    "summary": "论文提出因果感知的 LLM-agent 框架，用于从长篇新闻中抽取多类型事件及其异构论元；它把触发词识别、逐角色问答和因果关系推断结合起来，以补足分散或缺失的事件信息。",
    "question": "文档级事件抽取需要同时处理多个事件、不同论元模式和跨句线索，单纯依赖局部上下文容易漏掉地点、时间等角色。已有方法在长文中面对稀疏触发词和分散证据时，往往难以保持事件实例与论元之间的对应关系。",
    "method": "框架先用 LLM 定位事件触发词并判定事件类型；随后为每个事件建立按模式组织的角色队列，论元 agent 根据问答返回的 span、置信度和 NULL 结果迭代调整查询与局部上下文。最后，因果模块把事件之间的因果联系用于核验或推断共享的时间、地点等论元，同时保持预测可回溯到原文证据。",
    "experiments": "作者在两个公开文档级事件抽取基准上进行实验，并比较不同模块的作用。全文报告该框架在事件识别和论元抽取上优于对照方案，说明状态化角色问答与因果约束能提升长文中的抽取完整性；原文未把这一结果外推为对任意新闻体裁均有效。",
    "contribution": "工作把 LLM 的语义判断、可核验的问答证据和事件因果结构放入同一抽取流程，针对异构论元提供了更细粒度的控制。其效果仍依赖事件模式、问答模型和因果关系识别的质量；当文本证据本身不足或因果链错误时，推断步骤也可能传播偏差。\n---\nDOI: 10.1016/j.neunet.2026.109629",
