    "experiments": "实验覆盖图像分类、目标检测、实例分割和关键点检测，并与先进压缩基线比较。SaP 在压缩率、精度保持和实际效率上整体优于对照；例如 VGG-16 在 CIFAR-10 的多随机种子微调中平均准确率为 93.92%，标准差 0.08%，但该数字不能代表所有模型和任务。",
    "contribution": "贡献是把基共享与系数剪枝放入统一低维表示，提供跨视觉任务的实证。性能仍受优化器、微调策略、硬件实现和基空间配置影响，作者也指出这些因素可能改变压缩后的实际收益。\n---\nDOI: 10.1016/j.neunet.2026.109630",
