    "contribution": "该方法把高阶结构与多尺度时间建模整合到同一动态图框架，为稀疏演化图提供了统一表示路径。局限在于超图构建和时间注意力在超长序列或复杂结构上会增加计算成本，构图策略本身也会影响结果。\n---\nDOI: 10.1016/j.neunet.2026.109603",
