    "summary": "论文提出 Patronus：一个无需攻击标注数据和机器学习模型的应用层洪泛 DoS 检测决策框架，只用少量良性流量样本与管理员给定的先验信念来识别异常请求量模式。",
    "question": "应用层洪泛攻击的单个请求可近似正常，累积后却耗尽服务资源；依赖标注数据、攻击特征或固定阈值的方法难适应流量与攻击策略变化。系统需要能解释灵敏度、并可在线积累证据的轻量决策机制。",
    "method": "Patronus 用管理员设置的 belief value 表达良性样本中预期的攻击证据，再通过优化选择对结构性请求升高敏感的流量信号。在线阶段以带遗忘机制的证据决策模型对时间窗分类，原型设计意在补充既有入侵检测系统而非取代所有检测器。",
    "experiments": "作者在 CIC-IDS-2017 上以 30 秒时间窗评估，并比较 LDDM、阈值和 CUSUM 等决策引擎。结果显示高真阳性率和低误报率；计算分析指出信号提取占每窗处理时间的 90.5%，窗口查找占 8.8%，决策层不足 1%，说明新增决策开销较小。",
    "contribution": "工作把可解释先验、信号选择与证据衰减结合，降低了对攻击标签和特定模型的依赖。结论基于特定数据集和体量攻击，先验值与信号配置仍需面向业务流量校准，面对低慢攻击或复杂正常周期时可能需要额外机制。\n---\nDOI: 10.1016/j.cose.2026.105161",
