    "summary": "论文把拟态蜜罐中的攻击—防御过程建模为 Minimax-Q 博弈，通过评估多个业务执行体的欺骗价值、安全防御价值和开销，动态生成与调度防御策略，以同时提高诱捕能力和蜜罐自身安全性。",
    "question": "蜜罐可用无真实价值的诱饵吸引并观察攻击者，但攻击者正不断发展识别、规避乃至反向利用蜜罐的技术。静态蜜罐或仅按单项指标调整的方案难以在“足够像真实目标”和“不成为横向移动跳板”之间持续平衡；尤其在攻击者识别某个业务执行体后，固定配置会放大暴露风险。",
    "method": "作者在多级裁决机制上构造由多个业务执行体组成的拟态蜜罐，并为每个执行体定义结合欺骗价值、安全防御价值与计算开销的奖励函数。随后把攻击者与防御者的交互表示为攻击—防御博弈，用多智能体强化学习中的 Minimax-Q 求解贝叶斯纳什均衡，生成适应当前态势的策略；运行期的动态调度模块会替换可疑执行体，抑制攻击进一步影响其他主机。",
    "experiments": "原文在模拟环境中将所提拟态蜜罐与既有方案对比，并从攻击行为捕获、欺骗效果和内生安全性等角度评估。结果显示，Minimax-Q 驱动的动态调整在文中设定下更能维持防御优势；即使攻击者识别并针对部分执行体发起攻击，替换机制仍可把潜在威胁控制在较小范围。作者没有把模拟结论表述为真实生产网络中的必然效果。",
    "contribution": "工作将拟态蜜罐的执行体评价、博弈策略生成和运行期替换合并为一套自适应防御机制，为主动欺骗防御提供了可学习的决策框架。局限是验证主要基于仿真，奖励函数、攻击模型和执行体集合能否覆盖真实网络中的复杂攻击仍待检验；作者后续计划在真实网络部署中评估实际可用性和泛化能力。\n---\nDOI: 10.1016/j.cose.2026.105160",
