    "summary": "QiVC-Net 是用于心音（phonocardiogram, PCG）分类的量子启发式变分卷积网络，通过 QiRE 对卷积权重做保持几何结构的低维旋转集成，以在不显著增加参数的前提下获得更稳健、校准更好的不确定性建模。",
    "question": "传统确定性 CNN 只给出点预测，常难以反映医疗信号中的噪声、类别不均衡和分布扰动；部分贝叶斯近似又依赖各向同性噪声或 mean-field 假设，难以表示权重空间的结构化变异。作者以 PCG 分类为应用场景，关注如何把概率性与几何约束引入卷积层，同时避免高计算代价。",
    "method": "QiVC 的核心是 quantum-inspired rotated ensemble（QiRE）：在卷积核的低维子空间中执行可微旋转，借用幺正演化的数学类比来保持权重空间的范数与几何关系。QiVC-Net 将该层置入变分 CNN，以均值和标准差参数表达不确定性，并通过复合损失、动态权重、早停和分层交叉验证训练。论文强调该机制是“量子启发式”参数变换，并不依赖量子硬件。",
    "experiments": "在 PhysioNet CinC 2016 与 PhysioNet CirCor DigiScope 2022 两个 PCG 基准上，QiVC-Net 的准确率分别为 97.84% 和 97.89%。原文还在噪声扰动与类别不平衡条件下检查判别能力和置信度校准，报告模型保持较强的 specificity、具有竞争力的 sensitivity，并在可靠性图中呈现较保守的校准表现。比较结果支持其在该任务上的有效性，但并不构成对其他生物信号或临床部署的普遍性能保证。",
    "contribution": "论文的主要贡献是把结构保持的旋转集成引入变分卷积层，并在两套心音数据上同时考察准确率、鲁棒性与不确定性校准。局限在于验证集中于 PCG 和有限基准，量子启发式设计的收益仍需在其他模态、外部临床队列及不同噪声分布下复现；校准效果也依赖训练配置与评价协议，不能据此替代临床风险评估。\n---\nDOI: 10.1016/j.neunet.2026.109627",
