    "link": "https://doi.org/10.1145/3848128",
    "direction": "信息安全",
    "summary": "论文以 Dec-POMDP 与基于执行轨迹的信息流语义构建统一分析框架，归纳 agentic / multi-agent AI 的五类隐私泄露路径，并用受控多智能体沙箱说明 policy-checked 隐私机制能显著降低直接泄露和推断优势，却不能消除工具与语义线索带来的残余风险。",
    "question": "自主规划、委托、持久记忆、工具调用和多智能体协作使隐私泄露不再只来自单个模型输出：信息可在消息、共享状态、日志、外部调用和跨轮组合推理中扩散。既有 Privacy-Enhancing Technologies（PETs）往往假设计算边界静态、参与者固定或状态短暂，因此难以直接覆盖动态、多角色、长时程的 agent 系统。论文以医疗工作流为具象场景，但目标是提出架构无关的风险分析视角。",
    "method": "作者把分散决策过程与 trace-based information-flow semantics 结合，显式表示智能体观测、策略、工具、记忆、共享知识库、日志和对手可见的轨迹投影。据此整理五类路径：自主性导致的过度暴露、协调驱动的信息传播、记忆与持久状态泄露、涌现/组合式推断，以及可观测性与审计泄露。随后构建带 privacy-aware agent、policy checking、工具介导工作流和对手推断器的合成沙箱，并以五类 benchmark-style 情景校准分析。",
    "experiments": "受控验证覆盖 2 种架构、3 种隐私模式、5 类情景，每个单元 100 个 episode，共 3,000 个 LLM-backed episode。在最强的 privacy-aware + policy-checked 配置下，文中报告测试单元中未观察到直接秘密泄露或显式策略违规；相对无保护基线，对手推断优势在五类情景中下降 95.6%–98.9%。但工具调用轨迹和语义提示仍产生残余暴露，因此“零观察事件”只适用于该合成评估，不能解释为零泄露保证。",
    "contribution": "论文将动态 agent 系统中的结构性隐私风险、PET 适用边界和可复现实验性沙箱联系起来，尤其强调应在运行时治理信息流、工具、记忆与审计轨迹，而非只过滤最终输出。局限是沙箱使用合成敏感属性、固定情景和有限推断器，比较结果为描述性点估计而非真实部署的统计结论；更强对手、更多模型和更真实的跨组织工作流可能暴露新的风险。\n---\nDOI: 10.1145/3848128",
