    "direction": "信息安全",
    "summary": "MaskAug 是一种与具体网络结构无关的输入级数据增强策略：通过模拟部署时的特征缺失与损坏，提升网络入侵检测模型在受扰数据上的鲁棒性，而无需改动推理流程。",
    "question": "实际网络入侵检测常受传感器故障、网络中断和资源约束影响，导致输入特征缺失或被污染；实验室基准却常默认特征完整。已有鲁棒化方法往往与某种模型架构耦合，因此作者关注能否在训练数据层面构造通用干扰，使不同可微神经网络都能适应部署阶段的退化。",
    "method": "MaskAug 在分类器输入前施加三类互补扰动：随机掩蔽、块状掩蔽和按比例注入噪声，以模拟不同形态的特征退化。由于它只改变训练时输入，不修改下游分类器或在线推理管线，因此可作为 MLP、1D CNN、Feature Tokenizer + Transformer 等可微骨干的即插即用增强。原文摘要说明评测使用由官方 UNSW-NB15 与 CICIDS2017 重建并审计泄漏风险的基准，采用 10 组独立训练/评估划分和每组 3 个模型随机种子。",
    "experiments": "相对 clean-trained 基线，MaskAug 在 UNSW-NB15 上使 corruption-averaged Macro-F1 分别提高 0.043、0.060、0.072，在 CICIDS2017 上分别提高 0.087、0.150、0.057，对应 MLP、1D CNN 和 Feature Tokenizer + Transformer。摘要还报告，12 个预先指定的单侧 Wilcoxon 比较经 Holm 校正后均显著（调整后 p=0.012）；在 CICIDS2017 的掩蔽条件下，TF-IDF 基线 Macro-F1 为 0.33，而 MLP+MaskAug 为 0.92。以上数字来自公开摘要，完整实验细节仍需以正式全文复核。",
    "contribution": "该工作以零推理时额外成本的输入级增强，给出跨架构、跨数据集的受扰特征鲁棒性证据，并用预算匹配的重复干净样本对照排除仅由更多优化步数造成的收益。局限是目前未取得正式 PDF，作者、完整威胁模型、超参数和失败案例尚不能由本地全文核验；在机构 SSO 恢复并取得正式版后，应补读正文、补全作者信息并重新审查该总结。\n---\nDOI: 10.1177/0926227x261487917",
