    "direction": "人工智能",
    "summary": "LRSP-Fusion 提出一个可解释的通用多源图像融合框架：以低秩先验分离跨模态共享信息、以稀疏先验提取模态特有信息，再统一处理红外—可见光、医学、多曝光和多焦点等融合任务。",
    "question": "同一场景的多源图像既有背景等共享成分，也有纹理、显著目标等互补成分；现有方法常为某一融合任务专门设计，或以掩码、启发式网络做较粗的特征分离，跨任务适应性与可解释性都有限。论文将共享背景视作近似低秩结构、模态差异视作稀疏偏离，试图把这种结构性假设转化为可复用的融合模型。",
    "method": "模型采用两阶段编码与解码。Common Feature Encoder (CFE) 基于非负矩阵分解提取两幅源图的低秩公共特征；两条 Unique Feature Encoder (UFE) 将稀疏约束优化的迭代过程展开为网络，学习每个模态的特有成分。随后 Entropy-based Feature Fusion Block (EFFB) 用不同模态特征的熵计算融合权重，联合公共与特有特征重建融合图像；这种设计把特征分解的数学先验直接嵌入网络结构。",
    "experiments": "作者在红外—可见光、医学、多曝光和多焦点四类任务的多个公开基准上进行比较，并同时报告客观指标与主观视觉效果。全文结果显示，LRSP-Fusion 相比所列通用方法和任务专用方法在多类任务中取得更优融合质量；作者还报告该模型以更少参数获得较高效率。论文没有把任一单项指标概括为对所有数据集的绝对优势，结果应结合具体任务和评价指标理解。",
    "contribution": "贡献在于把低秩—稀疏分解用于通用图像融合，并以可展开的编码器和熵驱动融合块同时刻画共享与特有信息，减少为不同任务分别设计模型的需求。局限是作者明确指出融合模块仍含启发式设计，当前的理论可解释性主要覆盖特征分解而非整个融合流程；后续需要研究自适应融合机制，并检验其在更多模态和真实部署条件下的稳健性。\n---\nDOI: 10.1016/j.neunet.2026.109613",
