    "summary": "SIMC-ARTB 将锚点重构、对齐式多视图二部图融合、张量低秩约束和离散标签学习放在同一个优化过程里，用于处理视图缺失的不完整多视图聚类。",
    "question": "现实多视图数据常因传感器故障、采集成本或隐私限制而缺失部分视图。锚点二部图方法能降低大样本聚类开销，但已有工作多把锚点当作可靠代表，锚点质量一旦受缺失视图影响便会将偏差传入图结构；同时，常见“两阶段先学图、再聚类”的流程也未让图学习与离散标签相互校正。",
    "method": "论文提出 Single-phase Incomplete Multi-view Clustering via joint Anchor Refactoring and Tensorial Bipartite graph（SIMC-ARTB）。它先通过样本投影学习锚点，并用锚点重构约束锚点分布与原始数据的一致性；再以正交变换和自适应权重对齐各视图的不完整二部图，并施加加权张量核范数以保留跨视图的高阶相关和低秩一致性。离散标签学习直接嵌入上述联合优化，使图恢复与标签分配可共同迭代。",
    "experiments": "作者在 8 个不完整多视图基准数据集、不同缺失比例下比较多种方法。结果显示，SIMC-ARTB 在聚类准确性、稳定性和可扩展性上整体优于文中列举的现有不完整多视图聚类基线；实验还表明，锚点重构、对齐融合和张量正则化共同有助于获得更一致的图结构。原文的结论针对这些基准与设定，不应外推为任意视图数量或缺失机制下都占优。",
    "contribution": "该工作把锚点质量、图对齐、跨视图高阶结构和标签学习整合为单阶段框架，减少了前后阶段误差累积，并给出多缺失率场景的验证。局限是锚点数量仍由经验预先设定，锚点数与真实簇结构之间的关系尚未被显式学习；作者将自适应锚点配置和更有原则的选择准则列为后续方向。\n---\nDOI: 10.1016/j.neunet.2026.109618",
    "sample": false,
