    "question": "多视图 3D 分类可借助成熟的二维视觉骨干处理不同视角的渲染图，但简单池化或仅做全局聚合往往难以显式建模视图关系；不同角度间的异质性也会使特征融合不充分。作者聚焦于细粒度跨视图依赖与多尺度表达如何在同一模型中协同，而不是只增加更多视图或更深骨干。",
    "method": "网络以双分支共享的 Swin Transformer 提取两组视图特征，并接入 feature pyramid network 完成多尺度层级融合。Cross-group interaction 模块根据两组视图构造注意力式语义依赖矩阵，使一组特征可条件化地关联另一组上下文；双向 FiLM 再由对侧组的全局语义生成仿射调制参数，校准本组特征响应。训练阶段使用随机混合数据增强，提高正则化与泛化。",
