    "title": "Estimating adversarial transferability from feature-importance similarity in explainable intrusion detection systems",
    "authors": "Abdlelah Abdlatef、Marwa Abdulkareem、Duygu Cakir",
    "journal": "International Journal of Information Security",
    "year": "2026",
    "published": "2026-09-14",
    "contentState": "complete",
