    "doi": "10.1007/s10207-026-01333-y",
    "arxiv": "",
    "pdf": "papers/IJIS_2026_AdversarialTransferabilityFeatureImportance.pdf",
    "link": "https://doi.org/10.1007/s10207-026-01333-y",
    "direction": "信息安全",
    "summary": "论文表明，XGBoost 与 LightGBM 入侵检测模型的特征重要性相似时，针对一个模型生成的特征重要性引导对抗样本可能迁移攻击另一个模型；作者用 SHAP/LIME 和一个启发式相关性公式估计这种跨模型脆弱性，但不把公式当作确定性预测器。",
    "question": "机器学习入侵检测系统在正常流量上可以取得很高准确率，但攻击者只需对网络流量特征做小幅、看似合理的修改，就可能让恶意流量被判为正常。现有研究通常讨论单模型攻击或直接生成样本，较少把可解释性中的特征依赖与跨模型迁移联系起来。作者因此选择结构相近、都属于梯度提升树的 XGBoost 和 LightGBM，在 CICIDS-2017 与 NSL-KDD 数据上考察共享特征模式是否对应共享攻击面。",
    "method": "研究先清理常量和近常量特征，对非数值特征做序数编码，并对数值特征进行 Min-Max 归一化。随后分别训练 XGBoost 与 LightGBM，用 SHAP 和 LIME 解释预测并筛选高重要性特征；黑盒启发式搜索只在这些特征上施加满足 L2 范数和特征一致性约束的扰动。迁移实验把 XGBoost 生成的样本交给 LightGBM，反向过程也进行评估。作者定义两个模型特征重要性向量的 Spearman 相关系数 ρ，并提出以 (1+ρ)/2 乘以源模型攻击成功概率的启发式近似，明确说明它不代表决策区域的严格几何等价。",
    "experiments": "在 CICIDS-2017 上，直接攻击前 XGBoost/LightGBM 准确率为 97.41%/96.22%，攻击后为 91.23%/90.14%。从 NSL-KDD 的 10,000 个测试样本中生成 3,256 个对抗样本（32.56%），CICIDS-2017 的 12,000 个样本中生成 3,612 个（30.1%）；对应攻击样本被误判为正常的比例分别为 66.9% 和 63.9%。迁移攻击使 CICIDS-2017 上 XGBoost 准确率下降 8.75 个百分点、LightGBM 下降 10.59 个百分点；NSL-KDD 上分别下降 6.50 和 8.17 个百分点。两模型特征重要性 Spearman ρ=0.831，公式估计迁移率为 91.55%，实验观测为 86.4%，说明该式可作风险排序线索，但不能替代直接测试。",
    "contribution": "论文把 XAI 特征重要性用于识别 IDS 的可攻击特征，并在两个梯度提升模型之间实证了对抗样本迁移现象，给出一个可用于预估跨模型风险的启发式框架。局限包括：实验主要依赖静态公开数据，不能完全代表动态生产流量；方案没有消除对抗脆弱性，且只验证了结构相近的 XGBoost/LightGBM，不能直接推广到 SVM、随机森林等异构模型。未来需要更强的对抗训练、数据增强、实时部署评估和跨架构验证。\n---\nDOI: 10.1007/s10207-026-01333-y",
