    "direction": "信息安全",
    "summary": "Pacaller 将 Linux 内核网络资源分析、网络专用系统调用与数据包建模、以及系统调用—数据包协同执行结合起来，以发现单独进行系统调用或协议模糊测试难以触发的网络栈缺陷。",
    "question": "Linux 网络栈的状态通常同时受配置、系统调用序列、协议数据包和时序影响。传统系统调用模糊测试可能没有打开目标代码路径，协议测试又难以精确配合内核状态，因此两者各自运行会漏掉需要“先建状态、再注入数据包”才能触发的缺陷。作者希望自动找出可达配置、构造网络特定输入，并协调两类输入的执行时机。",
    "method": "Pacaller 首先从内核源码、Makefile 和 Kconfig 中提取网络资源与配置约束，通过关键词定位、AST 分析和类型解析生成可达配置；随后为提取出的资源生成 Syzlang 系统调用规格，并建立协议感知的数据包基础语料和变异算子。运行时利用覆盖率和 19 个内核函数上的 eBPF 探针跟踪状态与数据流，按覆盖收益和系统调用—数据包交互得分安排输入，协调系统调用执行与数据包注入。该流程覆盖 35 类协议，并针对不同内核版本重复生成和测试配置。",
    "experiments": "作者在 Linux 6.11、6.13、6.15 和 6.16 上进行评估。为期一周的发现实验找到 26 个此前未知的缺陷，其中 16 个已确认、10 个已修复；按触发来源计，默认系统调用贡献 3 个、网络专用系统调用 5 个、数据包 1 个、系统调用—数据包协同 17 个，自动生成配置额外打开了 5 个缺陷。24 小时对比中，Pacaller 平均覆盖 33,137.7 个目标，较 Syzkaller、SyzGen++、KernelGPT、Syz-TCP 和 TRON 分别高 22.3%、20.2%、18.3%、15.0% 和 13.3%；平均唯一崩溃数为 11.5，约为 Syzkaller 的 2.82 倍。消融实验显示，去掉系统调用规格、协同调度或数据包注入后，平均覆盖分别降至 30,874.7、30,609.6 和 29,308.6。",
    "contribution": "论文的核心贡献是把网络资源可达性、专用输入生成和跨输入类型协同调度放入同一套内核网络栈模糊测试流程，并用多个内核版本和真实缺陷结果证明协同部分的价值。局限是资源提取规则、Syzlang 模板和 eBPF 探针仍需适配目标内核；硬件相关网络驱动、设备仿真和更复杂的状态空间尚未被完整覆盖，当前的优先级策略也还有自适应化空间。因此结果不能直接等同于对所有网络驱动或所有内核配置的覆盖保证。\n---\nDOI: 10.1016/j.cose.2026.105141",
