    "link": "https://doi.org/10.1016/j.neunet.2026.109614",
    "direction": "人工智能",
    "summary": "PDMark 提出一种无需训练的扩散模型潜空间水印方案，用真实密钥与“看似真实”的伪密钥产生可否认分支，在保持图像质量与水印鲁棒性的同时，使持有者能够对强制披露提出可信的替代解释。",
    "question": "传统扩散模型水印通常把一个确定的消息绑定到图像上，一旦被强制要求交出密钥，审查者可能据此确认水印归属或敏感来源。作者将威胁设为一次披露后的强制审查，要求方案同时满足披露前难以检测、内容机密、披露时存在多个合理解释，以及披露后无法仅凭公开证据证明真实水印分支等目标。论文也强调，这种设定是有边界的，并不自动覆盖多轮审查或跨图像关联攻击。",
    "method": "PDMark 让真实消息与伪消息共享一部分同步结构，再用各自私有部分形成不同的二元关系。编码时先以共享组件生成同步头，再在由两条密钥约束确定的仿射解空间中承载数据，并通过与高斯分布相容的采样将结果嵌入扩散模型初始潜变量，最后用 DDIM 生成图像。提取端使用对应密钥恢复同步并读取消息；整个过程不需要重新训练水印网络。作者还加入截断尾部与重复比特掩码，以改善潜变量分布一致性和提取稳定性。",
    "experiments": "在干净图像对比中，PDMark 承载 2×128 bit，提取准确率为 1.000，FID 为 25.26，CLIP 相似度为 0.367。对噪声、模糊、中值滤波、JPEG、翻转、缩放、旋转和亮度变化等攻击，准确率分别约为 0.988、0.974、0.997、0.989、0.997、0.995、0.994、0.997；在扩散再生成、VAE 净化和 DiffPure 等净化测试中仍保持较高准确率。跨 Stable Diffusion v1.4、v2.0、v2.1 的迁移测试也接近 0.997–1.000。潜变量构造和提取耗时分别约 66.76 ms 与 0.92 ms，前者约占生成、反演和构造总耗时的 2.3%。",
    "contribution": "论文把“可否认性”落实到扩散模型潜空间水印的密钥与消息构造中，并在保真度、鲁棒性、净化攻击和跨模型迁移上进行了验证。局限也很明确：当前安全论证针对准备好的单轮、披露后强制审查，不能直接推出对多轮自适应审查的安全性；重复披露可能累积证据或暴露跨图像关联，方案还依赖真实/伪消息分布兼容、密钥管理正确以及元数据和侧信道不泄漏。后续仍需研究密钥演化、重复披露和更强的关联攻击。\n---\nDOI: 10.1016/j.neunet.2026.109614",
