    "title": "Detecting and mitigating IMSI catcher attacks: A formalized framework for secure mobile networks",
    "authors": "Hamad Alrashede, Faisal Albalwy, Hosam Aljihani",
    "journal": "Computers & Security",
    "year": "2026",
    "published": "2026-09-10",
    "contentState": "complete",
    "contentNote": "已依据出版社正式版全文完成中文六段式总结",
    "doi": "10.1016/j.cose.2026.105134",
