    "title": "Neural computation as operator-theoretic learning on measures",
    "authors": "Míngshū Wáng",
    "journal": "Neural Networks",
    "year": "2026",
    "published": "2026-09-09",
    "contentState": "complete",
    "contentNote": "已依据出版社正式版全文完成中文六段式总结",
    "doi": "10.1016/j.neunet.2026.109577",
    "arxiv": "",
    "pdf": "papers/NN_2026_Paper22.pdf",
    "link": "https://doi.org/10.1016/j.neunet.2026.109577",
    "direction": "人工智能",
    "summary": "本文把神经网络中的向量、图像、点云、图和 token 序列统一看作函数或带特征的测度，并将层、注意力和神经算子解释为通过采样、投影、求积或低秩截断得到的算子数值近似。",
    "question": "神经计算通常直接处理有限数组，但数组可能只是更有结构对象的表示：图像是网格上的函数，点云是经验测度，图信号是顶点上的函数，token 序列是带位置的经验测度。只比较矩阵和张量形式，容易忽略架构真正近似的对象、表示误差和离散化代价。论文希望建立一套共同语言，使架构选择能够回到测度空间、函数空间、核、拓扑和有限表示这些更基本的近似问题上，同时避免把统一表述误解为适用于所有架构的单一万能逼近定理。",
    "method": "作者用测度空间上的核算子表示神经层：核对输入函数或特征测度进行积分聚合，再经过特征变换和点态更新；有限计算则由样本、求积节点、基系数、图顶点、傅里叶模态或 token 完成。在线性核算子框架下，稠密层、卷积、注意力、图神经网络、graphon、神经场、核均值方法和神经算子被分别解释为不同的域、测度和核选择。论文还把误差拆成输入/输出表示误差、算子类误差、求积或采样误差和优化误差，讨论弱收敛、Wasserstein 距离、总变差、Sobolev/Besov 范数和 RKHS 度量下的稳定性，并分析 PCA、DCT、Nyström、稀疏或低秩注意力等有限化方式。",
    "experiments": "实验是诊断性验证，不是新预测架构或最先进性能竞赛。作者在 Iris、Wine、Breast Cancer 和 8×8 Digits 四个分类数据集上使用 5 次分层 70/30 训练测试划分，以准确率和宏平均 F1 比较原始坐标/网格、PCA、DCT、核均值分类器、Nyström 低秩特征和精确 RBF SVM。Iris 的原始有限场、PCA、Nyström 和 RBF SVM 平均准确率约为 0.9644；Wine 上 Nyström rank 128 达到 0.9815，高于精确 RBF SVM 的 0.9778；Breast Cancer 上精确 RBF SVM 为 0.9684，PCA 8 模态为 0.9673。Digits 上精确 RBF SVM 为 0.9819，原始 64 网格为 0.9667，PCA/DCT 32 模态约为 0.956，Nyström rank 128 为 0.9474，核均值类嵌入为 0.8889。表示维度或核秩增加时，PCA、DCT 和 Nyström 通常逐步接近完整表示；完整 Digits 附录还在 1,797 个样本上复现了这一趋势。",
    "contribution": "论文的主要贡献是给出一个把常见神经架构、测度表示、稳定性拓扑和离散化误差放在同一近似框架中的系统化表述，并提出应同时报告表示规模、采样规则、核秩或保留模态数。局限是理论结果主要是组织性框架和一般稳定性界，而非每类架构的最优逼近率；实验数据集规模小、任务单一，不能证明普适性能优势或离散化不变性；训练动力学、隐式正则化和有限样本泛化与算子逼近误差之间的关系也未被完整研究。因而本文更适合作为架构分析与实验设计的理论视角，而不是一个可直接替代现有模型的算法。\n---\nDOI: 10.1016/j.neunet.2026.109577",
