    "direction": "人工智能",
    "summary": "VLG-RMOT 先根据当前视频场景校准语言表示，再让校准后的语言参与查询初始化和解码器更新，从而提高自然语言指代下的多目标检测、关联和持续跟踪能力。",
    "question": "指代表达多目标跟踪要求系统在视频中找出并持续关联符合自然语言描述的所有目标。现有端到端方法虽然加强了视觉—语言对齐，但对齐并不等于语言已经适合控制随帧变化的对象查询：候选目标、外观和空间关系变化后，同一个词的重要性也会改变。若语言信号没有针对当前场景重新校准，视觉上显著但不符合表达的目标可能主导查询更新，造成误检、漏检或身份混淆。",
    "method": "VLG-RMOT 采用“先校准、后控制”的路径。跨模态语义校准模块 CSC 对视觉和语言特征做双向校准，并用可学习的逐通道残差缩放控制修正强度；上下文查询合成模块 CQS 在视觉解码前用校准语言建立指代先验、初始化查询；文本感知门控模块 TAG 在视觉交叉注意力之后再次调制查询状态。实现基于 RoBERTa、ResNet-50 和 Deformable DETR，训练时冻结文本编码器，并通过消融、缩放设计、token 变化和定性案例检验校准信号的作用。",
    "experiments": "作者在 Refer-KITTI、Refer-KITTI-V2 和 Refer-BDD 三个指代表达多目标跟踪数据集上以 HOTA 为主要指标。VLG-RMOT 在三个数据集上的 HOTA 分别为 52.70、35.68 和 39.18，在各自的端到端对比组中取得最佳结果；在 Refer-KITTI 上比第二名端到端方法高 1.79 个百分点，在 V2 上比 LTTrack 的 34.64 提高到 35.68，在 BDD 上同时取得较好的关联、检测精度和定位表现。Refer-KITTI 的组件消融中，去掉 CSC、CQS 和 TAG 的基线 HOTA 为 48.20，完整模型为 52.70；在匹配缩放实验中，可学习双向残差使 HOTA 达到 52.12，高于无 CSC 的 50.15。完整模型参数量由 174.51M 增至 181.21M、FLOPs 由 142.85G 增至 165.05G，推理速度由 35.82 FPS 降至 32.90 FPS，换取 4.50 个百分点的 HOTA 提升。",
    "contribution": "论文的贡献是把场景条件化的语言校准明确放到查询控制之前，并在查询生命周期的初始化和视觉后更新两个位置使用同一校准信号；逐通道缩放和 token 可视化也提供了表示层面的解释证据。局限包括密集且外观相似的目标、含糊的运动或状态描述，以及严重遮挡下仍可能出现混淆、漏检和暂时丢失。当前方法主要依赖可见外观和短期查询状态，对细粒度属性、时序关系和长期重识别记忆支持有限；因此，局部校准、运动关系建模和更长的 track-query 记忆是自然的后续方向。\n---\nDOI: 10.1016/j.neunet.2026.109615",
