    "title": "Carleman approximation based adaptive optimal control design of nonlinear systems: A three-phase policy iteration approach",
    "authors": "Jianguo Zhao, Zhijiang Gao, Chunyu Yang, Pak Kin Wong",
    "journal": "Neural Networks",
    "year": "2026",
    "published": "2026-09-10",
    "contentState": "complete",
