    "direction": "人工智能",
    "summary": "本文针对未知随机非线性系统，结合广义模糊双曲模型、带控制屏障函数的自适应动态规划和动态事件触发机制，同时处理非对称输入约束、运行安全和通信计算负担。",
    "question": "随机扰动和未知非线性动力学使传统模型驱动最优控制难以直接求解，而实际执行器的正负输入上限往往不对称。仅追求代价最优可能把系统推入危险区域，持续采样或持续更新控制器又会增加计算和通信开销。作者因此希望在不依赖精确动力学模型的情况下，学习安全最优策略，保证输入始终满足非对称约束，并通过事件触发减少不必要的控制更新。",
    "method": "作者用 GFHM 逼近未知系统动力学和随机诱导的非线性项，通过自适应参数更新降低建模依赖。针对非对称输入，构造修正的非二次价值函数；其中加入带阻尼因子的控制屏障函数，对接近不安全区域的行为施加惩罚。随后用单评论家神经网络和自适应动态规划近似求解修改后的随机 HJB 方程，得到安全最优策略。动态事件触发机制只在误差达到阈值时更新控制信号，并证明存在正的最小事件间隔；Lyapunov 分析用于证明系统状态及评论家权重估计误差的均方意义有界，并给出闭环安全性分析。",
    "experiments": "论文给出两个数值仿真例子，分别考察未知随机系统的辨识、闭环状态、控制代价、输入约束和安全区域避障效果。在第二个例子中，事件触发控制仅使用 196 个状态样本，而对照的时间触发过程使用 500 个样本，控制器更新次数最多减少 60.8%；输入信号始终落在非对称约束内，并在该算例中趋近约 -0.95 和 0.35。去掉控制屏障函数后，轨迹会进入预设危险圆域；加入屏障函数后保持安全。仿真还显示 GFHM 估计误差、系统状态和评论家权重按理论分析趋于有界，说明该方案能够在降低采样频率的同时兼顾安全约束与控制性能。",
    "contribution": "论文把 GFHM 未知动力学辨识、带屏障函数的安全最优控制、非对称输入处理和动态事件触发整合到一个强化学习控制框架中，并通过 Lyapunov 论证给出稳定性和有界性保证。局限是验证仍停留在数值仿真，尚未展示真实执行器、网络延迟或噪声传感器下的表现；理论结论依赖 Lipschitz 性、参数有界性、稳定设计矩阵和安全函数等假设；GFHM 及评论家网络的规模、调参和探索数据也会影响实际开销。后续仍需在更复杂的多输入系统、真实硬件和多约束场景中检验泛化能力。\n---\nDOI: 10.1016/j.neunet.2026.109610",
