    "question": "代码膨胀为攻击者提供大量可拼接的短指令序列，使 ROP/JOP 等代码复用攻击更易实施。已有去膨胀方法常依赖用户输入或配置，可能因删减过度破坏正常执行，也可能过于保守而留下大量攻击面。",
