    "experiments": "基础方案在 SPEC CPU 2017、GNU coreutils 和四类应用负载上的 gadget 平均削减率分别为 70.3%、88.5% 和 89.0%；内联扩展进一步达到 77.6%、94.7% 和 97.8%。SPEC 平均减速为 6.5%，Linux 与 Windows 案例中均破坏了生成 shell 的攻击链。",
    "contribution": "主要贡献是提出无需剥离功能的全程序攻击面缩减框架，并以编译变换进一步增强链破坏能力。其局限是结果集中于所选基准与服务程序，面对动态加载、即时编译及更复杂真实攻击链时仍需进一步检验。\n---\nDOI: 10.1145/3833877",
