    "method": "教师大模型先以多步知识抽取和融合产生高质量图谱训练数据，再微调较小的学生模型，实现高效端到端知识图谱构建。检索阶段根据生成器最终回答质量计算奖励，进行偏好优化，学习保留有效证据、删除无关三元组的子图剪枝策略。",
    "experiments": "作者在 HotpotQA、2WikiMQA、Natural Questions 和 MedHop 四个问答基准上评估，覆盖多跳、开放域和生物医学推理。结果显示 KD-GAG 在不同设置下保持稳定且有竞争力的性能，同时提高知识图谱构建和检索效率，并表现出低资源适应性。",
