    "pdf": "papers/TDSC_2026_GeneralizedDefense.pdf",
    "link": "https://doi.org/10.1109/tdsc.2026.3713473",
    "direction": "信息安全",
    "summary": "提出无需重训练的通用参数攻击防御框架 PARDEF，融合密钥通道重参数化、QC-LDPC 编码量化与自适应鲁棒推理，在稀疏、连续与结构化三类参数攻击下均显著降低攻击成功率并保持模型精度。",
    "question": "深度神经网络被广泛部署于云存储、CI/CD 流水线、容器化服务与边缘执行等异构且部分不可信环境中，模型参数的完整性与可信度面临供应链篡改、不安全分发等多类风险。与输入空间的对抗攻击不同，参数攻击直接篡改模型内部权重，可在不改变输入输出接口的情况下持续影响后续所有推理，且能绕过输入级防御。参数攻击按扰动方式可分为三类：稀疏攻击（L0 有界，如 ProFlip 位翻转）、连续攻击（L2/L∞ 有界，如 APA 对抗参数攻击）以及结构化攻击（如 P3A 沿通道/层协同篡改）。既有防御或需重新训练且精度损失大（如 BIN、RA-BNN 的激进量化），或仅针对单一攻击类别（如 Aegis 专用于位翻转），无法应对现实部署中形式难以预料的参数攻击，因此需要一种覆盖多类攻击且实用化的通用防御。",
    "method": "作者提出 PARDEF，一个\"准备—推理\"两阶段的通用防御流水线，由三个协同模块组成，且无需重训练即可直接应用于已训练模型。(1) 密钥通道重参数化（KCR）：按层为权重通道施加由密钥驱动的置换与正对角缩放变换，将敏感参数方向打散并错开基于梯度的攻击定位，同时通过边一致性、分支对齐与端点约束证明变换后的网络与原网络严格功能等价（零推理开销）。(2) QC-LDPC 编码量化：将权重以 8-bit 仿射量化后用准循环低密度奇偶校验码（速率 0.875、块长 Nb=128）分组编码，在缩小模型体积的同时引入纠错冗余，加载时一次性译码，可纠正位翻转、把小幅连续漂移映射回合法码字，对超范围篡改则检测并在加载时失败停机。(3) 自适应鲁棒推理（ARI）：推理时注入小幅高斯噪声（σw=10⁻⁴）进行多次随机前向（快路径 Ms=5），以置信度裕度 Δ(x) 与阈值 τ 判断是否升级到投票式慢路径（Mℓ=25），仅对高风险输入分配冗余计算。攻击模型设定为玻璃箱、防御感知且可使用 EOT 的自适应对手，针对的是加载前的静态（at-rest）参数篡改，并采用 TEE/HSM/TPM 分级密钥保护模型。",
    "experiments": "在 CIFAR-10、CIFAR-100、Tiny-ImageNet 上用 VGG16 与 ResNet32 评估，对照 Base、Aegis、BIN、RA-BNN 四个基线，攻击采用 ProFlip（翻转预算 {25,50,75,100}）、P3A（扰动通道数 {1,3,5,7}）与 APA（L∞ 幅度 {1/255…16/255}），并设计了防御感知的自适应与联合自适应变体。RQ1 精度保持：PARDEF 的 ΔACC 最小，BIN/RA-BNN 的精度下降约为其 2–4 倍；复现的 Aegis 在 CIFAR-10/ResNet32 上下降 17.20%（原论文为 1.26%）。RQ2 鲁棒性：PARDEF 在 P3A 与 APA 下所有数据集与预算上 ASR 均最低，ProFlip 下接近 Aegis 且各预算稳定；面对自适应攻击，PARDEF 相对 Base 降低 ASR 约 40–70%；联合自适应攻击下 Joint-P3A/Joint-ProFlip/Joint-APA 的 ASR 分别上升 7.97–10.81、6.46–8.83、4.34–6.61 个百分点，但仍低于未防御 Base。RQ3 开销：模型体积普遍缩减约 70%（ResNet32 由 1.94–1.98 MB 降至 0.57–0.58 MB，VGG16 由 58.92–60.48 MB 降至 17.33–17.78 MB）；P50 延迟增加约 0–7%、P90 约 4–9%，全量慢路径最坏情况约为 P50 的 3.5–4 倍。RQ4 消融（CIFAR-10/ResNet32）显示移除 KCR 主要损害结构化攻击、移除 QC-LDPC 主要损害稀疏攻击与体积、移除 ARI 主要损害密集小幅噪声鲁棒性，三模块互补性明显。Transformer 扩展实验（DeiT-Tiny/DeiT-Small 于 ImageNet-1K 与 CIFAR-100）：干净精度仅下降 1.37–2.46 个百分点；ProFlip 的 ASR 由 89.92–96.74% 降至 36.48–43.52%，P3A 由 85.35–91.38% 降至 47.29–54.17%，APA 由 40.28–57.63% 降至 11.36–18.94%；DeiT-Tiny 由 22.83 MB 降至 6.72 MB、DeiT-Small 由 88.31 MB 降至 25.96 MB。附加分析显示：QC-LDPC 可纠正 65–70% 的受扰块、30–35% 检测但不可纠、静默误纠低于 0.6%；ARI 慢路径触发率在干净输入下约 10%、APA 攻击下最高达 35.5%；KCR 置换熵随通道数 C=32/64/128 约为 log2(C!)≈118/296/716 bit，ResNet32 分级密钥空间保守估计超 450 bit；加载前篡改保持较高 ACC，而加载后内存篡改（超出范围）导致严重精度下降。",
    "contribution": "主要贡献：提出首个面向稀疏、连续、结构化三类参数攻击的统一防御 PARDEF，无需重训练且不依赖攻击特定假设，通过 KCR 严格等价证明、QC-LDPC 编码量化与 ARI 自适应推理实现\"精度—体积—延迟\"的良好平衡（约 70% 体积缩减与较小的典型延迟开销），并给出了向 Vision Transformer 架构的等价扩展与四档部署信任分级及密钥生命周期管理，附带公开复现工件。局限：最强保障依赖 TEE 等受保护密钥环境（Tier 1），无安全存储时 KCR 混淆失效；仅覆盖加载前静态篡改，加载后内存级篡改需 ECC DRAM、Intel TDX 等硬件层机制配合；实验主要限于中等规模 CNN/ViT 图像分类模型，尚未在 LLM 或生成模型规模验证，也未评估 ECE/NLL 等校准指标；QC-LDPC 存在残余译码错误，ARI 慢路径在高负载攻击下可能被滥用放大开销（内置升级预算可约束）；高度自适应、针对防御组件的攻击仍可能带来额外挑战。\n---\nDOI: 10.1109/tdsc.2026.3713473",
