    "summary": "论文提出图中心周期调度（GCPS），利用通信图的代数连通性、节点多样性和中心性选择联邦学习客户端，以避免低轨卫星网络中局部地面站出现零召回。",
    "question": "低轨卫星的周期性、空间相关可见性会使部分地理区域长期较少参与训练，安全事件检测因此可能对某些地面站完全失明。平均准确率、收敛速度或 Jain 公平指数可能掩盖这种局部灾难，而常规随机、损失驱动和通信启发式调度没有直接约束训练子图的连通性或最差节点性能。",
    "method": "GCPS 每轮综合介数中心性、反近因参与多样性、Fiedler 向量贡献对应的谱重要性和节点度，构造客户端评分并选择得分最高的可见地面站。它用只访问验证集的多臂老虎机，在七组预设权重之间动态调整，且保持安全相关的多样性与谱项不低于 0.25；测试集只用于最终评估。方法在 Walker Delta 可见性和地面站通信图上运行，把保持诱导训练子图的代数连通性作为减少区域隔离的结构机制。",
    "experiments": "实验在 MATLAB 模拟的 Walker Delta 星座、60 个地面站、339 条图边和 80 个通信轮次上进行，使用 5 次独立试验比较 GCPS 与 9 个基线。GCPS 的零召回节点为 0/5 次，而 GeoDiversity 为 5/5、GraphWeighted 为 4/5、AFL 和 q-FFL 各为 2/5；平均假阴性率为 0.281，GeoDiversity 为 0.969，GraphWeighted 为 0.922。GCPS 的最差节点召回率为 0.242，Jain 指数为 0.990；其训练子图平均约 44 条边，GeoDiversity 约 23 条。每轮调度开销约 3.3 ms，相比随机选择的 1.7 ms；在 40% 标签翻转攻击下，GCPS 准确率比 FedAvg 高 0.030。",
    "contribution": "贡献包括把谱图连通性直接用于联邦客户端调度，提出不接触测试集的动态权重机制，并将最差节点召回、最小节点准确率和假阴性率作为安全关键评估指标。论文同时证明高 Jain 指数不代表性能公平。局限是轨道与通信图仍为简化静态模拟，尚未用真实卫星接触轨迹或硬件测试；形式化差分隐私保证、动态拓扑下的可扩展特征分解、更多安全指标和连续权重优化仍待研究。\n---\nDOI: 10.1007/s10994-026-07159-y",
