    "direction": "人工智能",
    "summary": "AI Harmonics（AIH）把不同利益相关方之间 AI 危害的集中程度量化为适用于有序严重性等级的公平性指标，从而支持以人为中心、对危害严重性自适应的风险排序。",
    "question": "现有 AI 风险框架常由内部合规或组织控制视角出发，忽略外部利益相关方，也经常把本质上是序数的危害等级强行映射为任意数值。这样既难表达“危害是否集中在少数群体”，也可能在等级定义变化或标注不完整时改变优先级。论文围绕三个问题展开：如何纳入人的判断，如何在不假设数值间距的情况下排序风险，以及排序是否足够稳健、可适应。",
    "method": "作者从 AIAAIC AI 事件库中整理利益相关方—危害类别—严重性标注，涉及自主性、情绪/心理、金融/商业、人权、身体、政治/经济、心理、声誉、社会/文化等危害类型。AIH 将每一类别的序数严重性频数构造成离散 Lorenz 曲线，用扩展 Gini 思路计算危害集中度，并与 Criticality Index（CI）结合，关系式为 `AIH = CI*(M-1)/M + 1/(2M)`；计算复杂度为 O(K + NM)。流程包括数据筛选、利益相关方标注、严重性排序、指标计算和风险优先级输出；同时进行边界、扰动和随机删减标注的稳定性分析。",
    "experiments": "九类危害的 AIH 分别为：自主性 0.53、情绪/心理 0.70、金融/商业 0.51、人权 0.67、身体 0.73、政治/经济 0.85、心理 0.73、声誉 0.67、社会/文化 0.70；政治/经济危害的集中度最高，金融/商业和自主性最低，身体危害也较高。AIH 与 CI 在严重性扰动下的 Spearman 秩相关达到 0.97–1.00；随机移除最多 80% 标注时，最高和最低类别的身份仍保持稳定。结果说明该指标既能保留风险排序，又不依赖任意的等距数值编码。",
    "contribution": "贡献在于把利益相关方分布、不均匀危害严重性和鲁棒风险排序统一到一个可计算框架中，并给出可用于政策和治理优先级的实证结果。局限是事件报告与标注可能存在选择偏差，数据未覆盖所有真实风险；严重性顺序依赖语境，AIH 只能描述危害集中与优先级，不能建立因果关系、预测事件或直接给出缓解方案。未来需要动态数据、多套利益相关方排序以及因果模型。\nDOI: 10.1016/j.artint.2026.104587",
    "sample": false,
