    "direction": "信息安全",
    "summary": "面向机器学习即服务（MLaaS）场景提出基于影响子图的认证图反学习框架 SCGU，使服务提供者无需训练数据、仅凭与反学习目标相关的子图即可直接修改模型参数完成节点、边或特征反学习。",
    "question": "图神经网络（GNN）已广泛用于推荐、金融与生物信息等领域，其部署常以 MLaaS 形式形成数据所有者、模型开发者与服务提供者三方生态（如 Careem 与 AWS Neptune ML 合作的反欺诈 RGCN 案例）。训练后的 GNN 会残留用户隐私信息，攻击者可借成员推理攻击（如 MIA-Graph、StealLink）获取节点或边信息，而 GDPR、CCPA 等法规赋予用户\"被遗忘权\"。现实约束在于：服务提供者只持有模型、不掌握训练数据，而现有认证图反学习方法通常假设可访问整张图、基于全图计算 Hessian 与梯度差来估计参数变化，或需要修改 GNN 架构与训练流程（加层、分片、参考模型等），与 MLaaS 常规部署不一致，难以由服务提供者直接执行。因此需要一种只使用与反学习请求相关数据、兼容既有部署、且可由模型开发者或服务提供者灵活独立执行的反学习方法。",
    "method": "作者提出子图级认证图反学习（SCGU）框架，由预计算、子图采样与模型反学习三个流程组成。预计算阶段，模型开发者在训练末尾记录全部权重及最后两个 epoch 的梯度之和（即全局 Hessian 分量）并上传给服务提供者，梯度聚合使单个样本信息难以反推。子图采样阶段，数据所有者依据 GNN 的 k 层消息传递机制，以反学习目标为中心定义\"影响子图\"（目标节点及其 k 跳邻居构成，用于计算梯度差的损失项），并采用结构扰动机制在逐跳扩展中随机掩蔽邻居与边，形成带噪声的近邻子图以避免邻域爆炸与无关节点暴露。模型反学习阶段，服务提供者对影响子图内节点做随机特征扰动，依据条件独立系数指标 L-CODEC 贪心选出与反学习目标最相关的参数子集，仅对该子集用训练最后两轮的梯度差经有限差分估计 Hessian，结合受影响节点反学习前后的梯度差按影响函数原理（式 12）直接更新模型参数。文中还证明在上述图局部化与参数局部化近似下，随机化输出满足松弛的 (ε′, δ′) 认证反学习，其时间复杂度为 O(m|θ| + m|θ|log m + |θP|³)，空间复杂度为 O(4|θP|)，并支持批量反学习与序列请求的参数状态同步。",
    "experiments": "实验覆盖 3 种反学习任务（节点、边、特征反学习，各删除不超过 5% 的相应实例）、5 个数据集（Cora、CiteSeer、PubMed、Coauthor-CS、Coauthor-Physics）与 4 种骨干模型（GCN、GAT、GIN、SGC），基线为 Retrain、GraphEraser（BLPA/BEKM）、CGU、CEU 与 IDEA，服务器配置为 4 颗 Intel Xeon Gold 6348 CPU 与 5 块 Nvidia A100 GPU，采用 PyTorch 与 PyTorch Geometric 实现。结果表明：SCGU 比重训练至少快 4 倍，得到的参数与重训练模型更接近（接近程度提升 3%–5%），且在大多数场景下除重训练外的所有基线在模型效用与反学习功效上均被 SCGU 超越；例如 Cora 上 GIN 做节点反学习时 SCGU 的 F1 为 84.62，高于 IDEA 的 83.69，且 L2 参数距离在多数数据集与模型上低于 IDEA。功效方面，节点反学习后 SCGU 在 4 个测试场景取得最优、并在其余 16 个场景中的 9 个胜过基于重训练的方法；边反学习后在 20 个场景中的 14 个取得重训练类方法之外的最优 AUC；特征反学习用平均损失衡量，过半数据集与模型上 SCGU 的结果最接近 Retrain。删除推断攻击下重训练类方法 AUC 约为 0.5，CEU/IDEA 部分场景存在明显偏差，SCGU 在多数场景与之相当。采样策略实验（CS 数据集、GCN/SGC）显示，当逐跳采样数 bl=1 时仅上传完整影响子图 33% 的节点（暴露节点减少约 67%），而模型效用与反学习功效（AUC 接近理想值 0.5）几乎不变。",
    "contribution": "贡献包括：据作者所述，SCGU 是首个允许 MLaaS 场景下服务提供者直接修改模型参数完成图反学习的框架；通过近似估计把反学习后的参数分解为多个分量，服务提供者只需影响子图即可反学习，把与目标无关节点的隐私泄露风险降到最低；提出结构扰动机制，以注入受控拓扑噪声的方式在隐私保护与反学习效果之间取得可调节的权衡；无需修改 GNN 架构或训练流程，天然兼容 MLaaS 现有部署。局限方面：结构扰动采样策略属于经验驱动而非理论最优，作者仅将其视为结构与隐私暴露间的折中，未提供正式隐私保证；理论分析依赖损失函数 L-Lipschitz 连续且 λ-强凸等假设；未来工作包括将该权衡形式化、给出影响子图最小性或最优性的更强保证，并探索降低反学习计算开销的更优近似方法。\n---\nDOI: 10.1109/tdsc.2026.3715465",
