    "link": "https://doi.org/10.1109/tdsc.2026.3715456",
    "direction": "信息安全",
    "summary": "针对云外包加密数据上的多维范围查询，本文提出轻量在线/离线方案 SLIMQ：用 R 树与前缀编码把查询化简为前缀匹配问题，基于自适应的三方秘密共享构造私有前缀匹配、点相交与区间相交测试协议，在实现完整单维查询隐私的同时把在线阶段计算降到最轻。",
    "question": "- 医疗、金融、IoT 等数据密集型应用催生了大规模多维数据集与高频的范围查询需求，而数据所有者在本地存储和算力上受限，外包到云上成为现实选择，但不可信云服务器会带来严重的隐私泄露风险。\n- 现有方案各有缺陷：保序加密（OPE）天然支持范围比较但泄露明文统计分布；分桶（bucketization）方案把大量计算转嫁给资源受限的查询用户；基于公钥加密（双线性对）的方案开销过大，难以支撑大规模应用。\n- 较新的轻量方案（对称加密 + R 树/线段树索引）提升了效率，但大多泄露每个维度各自的查询结果，即单维查询信息；TRQED+ 通过 oblivious R 树遍历隐藏访问模式，PRQ 虽能实现完整单维查询隐私，但其矩阵编码规模依赖数值域上界 N²，数据域变大时存储与计算开销急剧增长。\n- 因此核心挑战是：在保证高在线查询效率的同时实现完整单维查询隐私，并支持离线预计算以减轻在线负担。",
    "method": "- 数据表示与查询变换：用 R 树索引多维数据集，将内部节点 MBR 端点与叶节点数据统一编码为 w 位二进制；采用前缀编码把一个多维范围查询表示为最小前缀集，并把 R 树范围查询中的点-区间相交与区间相交测试归约为前缀匹配问题（区间相交等价于端点对 [0, qi,r]、[0, qi,l−1] 前缀集的匹配判定）。\n- 自适应三方秘密共享 ΠaTPSS：面向外包查询场景改造的三方（CS1、CS2、CS3）秘密共享，基于 PRF 非交互生成随机份额，数据所有者只需为每比特数据传递 1 比特给服务器，AND 乘法的重计算放离线阶段。\n- 私有算法族：基于 ΠaTPSS 构造私有前缀匹配算法 ΠPMatch（判断数值是否匹配前缀编码值），并在此基础上构造私有点相交测试 ΠPInter 与私有区间相交测试 ΠRInter；三者均采用离线–在线模式，计算密集任务在离线阶段完成，在线阶段仅做轻量异或/与操作。\n- 完整方案 SLIMQ：由 Setup、Data Outsourcing（构建并秘密共享加密 R 树 [[T]]）、Query Token Generation（生成 [[q]]PInter 与 [[q]]RInter 两个查询令牌）与 Query Processing（递归遍历 [[T]]，内部节点用 ΠRInter 剪枝、叶节点用 ΠPInter 判定，命中结果由服务器份额让用户本地恢复明文）四个组件组成，查询复杂度为 O(d·w²·log|X|)。",
    "experiments": "- 实现与设置：用 C++11 实现，测试环境为 AMD Ryzen 9 7945HX @2.50GHz、32GB RAM、Windows 11；R 树内部节点最大子节点数设为 8，安全参数 κ=256，每组实验重复 50 次（令牌生成实验重复 10,000 次取平均）。\n- 数据集：使用公开的真实糖尿病临床数据集（Kaggle 100000-diabetes-clinical-dataset），选取 year、age、heart disease、BMI、HbA1c level、blood glucose level 六个属性，数据经缩放平移为正整数。\n- 对比基线：与 PRQ 与 TRQED+ 对比；PRQ 的域参数 N 取 45（容纳数据最大值 2022）；TRQED+ 按不带 tagged-label 的低开销版本实现，因为其标签机制专用于隐藏访问模式。\n- 结果：随数据集规模 |X| 增长，SLIMQ 的查询时间呈亚线性增长，随维度 d 线性增长；在线查询阶段相比 TRQED+ 有超过一个数量级的效率提升，离线阶段开销与 TRQED+ 相当；查询处理通信开销约为 TRQED+ 的一半；由于基本运算是 Z2 上的乘法，比对比方案在实数上的运算更快；但三者都是基于 R 树的检索，d 超过 4 后高维性能明显退化。",
    "contribution": "- 贡献：(1) 用前缀编码把 R 树多维范围查询转化为前缀匹配问题，查询开销为 O(d·w²·log|X|)，摆脱 PRQ 中数值域上界 N² 的依赖；(2) 提出面向外包场景的自适应三方秘密共享 ΠaTPSS，减少数据所有者通信开销；(3) 设计 ΠPMatch、ΠPInter、ΠRInter 三个离线–在线私有算法，在线阶段仅需轻量运算；(4) 在真实医疗数据集上的实验表明在线查询效率显著优于 PRQ 与 TRQED+，且经模拟式安全分析证明能保护数据隐私、查询隐私与完整单维查询隐私。\n- 局限：(1) 仅在三个非共谋半诚实服务器模型下安全，不抵抗恶意服务器，也不提供结果可验证性（区别于 [30]–[32] 的可验证方案）；(2) 不隐藏访问模式（完整版 TRQED+ 通过 tagged-label 与 oblivious 遍历隐藏访问模式，但开销更高）；(3) 基于 R 树的结构不适合高维数据，d 较大时性能退化；(4) 未来工作拟扩展支持动态数据更新、恶意敌手模型与大规模联邦查询场景。\n---\nDOI: 10.1109/tdsc.2026.3715456",
