    "title": "Long-Short-Term Decoupled Residual Learning for High-Resolution Spatio-Temporal Air Quality Inference",
    "authors": "Hui Zheng, Jialing Huang, Huiming Chen, Zhenlong Xiao, Nengwang Chen, Xinghao Ding",
    "journal": "Neural Networks",
    "year": "2026",
    "published": "2026-09-01",
    "contentState": "complete",
    "contentNote": "已基于机构授权全文完成中文六段式总结",
    "doi": "10.1016/j.neunet.2026.109575",
    "arxiv": "",
    "pdf": "papers/NN_2026_LongShortDecoupledAirQuality.pdf",
    "link": "https://doi.org/10.1016/j.neunet.2026.109575",
    "direction": "人工智能",
    "summary": "本文提出时空空气质量推断网络 SAQIN，将推断显式分解为长期静态环境先验与短期动态扰动并做基于参考站的残差校正，在长三角 171 个监测站等真实数据集上全面超过现有方法，并具备零样本跨域泛化能力。",
    "question": "在监测站稀疏且分布不均的条件下，做高分辨率、时空连续的空气质量推断对环境治理与公共健康至关重要。现有深度学习方法大多把推断当作对浓度的直接回归，忽略了观测浓度由长期静态基线（土地利用、人口密度、地形等稳定因素）与短期动态扰动（风输送、光化学等瞬态大气过程）叠加而成，导致机理混淆、在未见区域泛化差并产生系统性空间偏差。同时，遥感影像常被当作普通像素输入或退化为 NDVI 等粗糙指标，无法显式刻画工业区、道路等污染源；而依赖固定参考站的推断隐式把连续浓度场离散成 Voronoi 单元，在分区边界产生不连续，违背大气扩散的物理平滑性。",
    "method": "SAQIN 采用静态–动态双分支解耦结构。静态分支利用 DeepLabV3（ResNet50 骨干，在 LoveDA 上预训练）做高分辨率语义分割以恢复建成区、道路、水体等污染相关土地利用语义，再以堆叠 RepViTBlock 的轻量全局上下文提取器补充宏观空间格局，并融合人口密度与海拔的表格特征，构成高保真环境先验。动态分支以参考站多污染物实时浓度（CO、NO2、O3、PM10、PM2.5）、与目标的测地距离及方位角（Haversine 公式）、以及参考站自身静态特征为输入，经多头自注意力联合建模地理关系与污染物间化学耦合。推断被重构为残差校正任务：预测目标相对各参考站观测值 Ci 的浓度偏移 Δŷ，再残差相加重建浓度，从而内在地消除未知的区域静态偏差、专注学习局部平滑扰动。最后用逐步多站融合模块，从目标点 25 km 半径起逐级扩大（每次 25 km）选取 N 个候选站（训练随机采样、推断取最近 N 站，N=4），按 1/√d 距离加权平均聚合各站预测，消除 Voronoi 诱导的不连续，重建全局平滑、物理合理的连续浓度场。损失由 Smooth L1、Log-L1 与尺度不变（对数域平方差）三项等权重（λ1=λ2=λ3=1）组合而成。",
    "experiments": "实验使用长三角 171 个监测站数据（2021-01-01 至 2023-12-31 训练、2024-01-01 至 2024-11-16 测试），融合 Sentinel-2 遥感影像（10m）、WorldPop 人口密度（1km）与 GEBCO 海拔（0.5km）；以 R2、MAE、MRE、RMSE 为指标，与 KNN、GPR、IGNNK、INCREASE、STGNP、DualSTN、STFNN、AirRadar 等基线对比。SAQIN 在 O3、NO2、PM2.5、PM10、CO 上 R2 分别达 0.9474、0.8842、0.9542、0.9509、0.6485，MAE 较 AirRadar/STGNP 最高降低约 25%、RMSE 最高降低约 30%。在仅用北京 32 站训练、零样本直接迁移到长三角的跨域实验中，O3、PM2.5、PM10 的 R2 仍达 0.9198、0.9387、0.9422。消融实验（深圳 15 站 O3、PM2.5 数据）表明语义分割、遥感特征、多污染物耦合（PM2.5 与 PM10 相关系数 r=0.74）、距离/方位与残差校正均贡献明显——去掉残差校正后 NO2 上 R2 从 0.8842 降至 0.8767；三合一复合损失优于任何单损失或两两组合；参考站数 N=4 精度与效率最优。完整 SAQIN 参数量 41.46 M、FLOPs 2.30 G、单次推断 113.09 ms（单张 NVIDIA RTX 3090）；去除遥感图像分支后核心时空推断仅 0.10 M 参数、0.0004 G FLOPs、51.52 ms。",
    "contribution": "- 提出 SAQIN 双分支框架，显式解耦长期静态环境先验与短期动态变化，推断结果具有物理可解释性；\n- 以语义级遥感表征（预训练语义分割 + 轻量全局上下文）代替像素级或 NDVI 式用法，提供物理含义清晰、刻画空间非平稳性的环境先验；\n- 设计基于参考站实测观测的残差校正与逐步多站距离加权融合，消除未知静态偏差和 Voronoi 分区不连续，生成全局平滑、物理合理的连续高分辨率浓度场；\n- 在长三角五种污染物推断与跨域零样本迁移（北京→长三角）上全面超越现有方法。\n局限：模型依赖距离、方位等几何代理表征大气输送，可能无法完全刻画复杂的气象动力学过程。\n---\nDOI: 10.1016/j.neunet.2026.109575",
