    "title": "An Automated Exploitability Analysis Method Based on State Machines",
    "authors": "Qiang Ruan, Zihang Liu, Chunlai Du, Li Ma, Yanhui Guo",
    "journal": "Computers & Security",
    "year": "2026",
    "published": "2026-09-04",
