    "link": "https://doi.org/10.1016/j.cose.2026.105140",
    "direction": "信息安全",
    "summary": "提出基于 Exploit State Machine（ESM）与 Verifiable Exploit Primitives（VEP）的自动化漏洞可利用性分析模型 EAG，将利用过程建模为可验证的状态转移，并输出结构化可利用性证据（SVEAA），在 25 个 CTF Pwn 程序与两个历史 CVE 上优于 Zeratool 与 SAEG。",
    "question": "软件漏洞数量激增（NVD 统计 2025 年 CVE 数量超过 4.8 万，2020–2025 年间提交量增长超 260%），63% 的网络安全从业者无法对海量漏洞做细致人工分析，需要自动化可利用性评估辅助决策。现有 Automated Exploit Generation (AEG) 技术存在两大缺陷：一是漏洞利用路径探索策略僵化，难以应对需要复杂状态或分段交互的多阶段利用链、非控制数据攻击等场景；二是多数工具只给出成功/失败的二值结论，而分析人员需要理解完整利用逻辑、关键步骤与前置条件。CVSS 评分也存在主观性强、缺乏可利用性上下文的问题。",
    "method": "论文提出 EAG（Exploitability Assessment Generation）模型，抛弃\"直接生成最终攻击载荷\"的传统目标，转而将漏洞利用过程形式化为受 Exploit State Machine (ESM) 驱动的状态转移过程。首先定义 VEP（Verifiable Exploit Primitive），以三元组（NAME, PV, EV）抽象单个利用或信息收集步骤，包括信息泄露类（如 Puts Leak、Stack Pivot）与利用类（Ret to libc、Ret to win、Ret to shellcode、Ret to dlresolve）两类；再以 ESM 五元组（𝕊, A, s0, δ, G）进行带优先级的确定性状态空间搜索：优先尝试能直接达成目标的利用类 VEP，前置条件不满足时才执行泄露类 VEP 扩展知识库 K，取得新知识后重新优先尝试利用类 VEP，并通过 NewKnowledge 条件与历史记录避免循环。每个 VEP 的可行性通过符号执行与约束求解（如 PC 等于目标地址、required_bytes≤available_bytes）验证。最终输出由五部分构成的 SVEAA（Structured and Verifiable Exploit Action Attributes）：利用概要、前置条件评估、关键内存布局、利用路径构建与可利用性评级，仅在全部条件满足时评级为 HIGHLY。",
    "experiments": "作者基于 angr、pwntools、Z3 与 radare2、以 Python 3.8（Ubuntu 22.04 64 位）实现原型系统 EAGS，在从 CTFTime 收集的 25 个 CTF Pwn 程序及两个真实漏洞（Aspell word-list-compress 的 CVE-2004-0548、dnstracer 的 CVE-2017-9430）上，与 Zeratool、SAEG 对比，每个工具运行 20 次。CTF 测试中 Zeratool、SAEG 在大部分挑战上超时或失败（记为 N/A），而 EAGS 成功完成全部 25 个程序，用时 0.37–12.19 秒（如 p0wn3d 0.37 s、not a baby rop 10.06 s）；两个 CVE 上 EAGS 分别以 1.19 s 与 28.19 s/30.43 s 输出结构化 SVEAA，Zeratool 与 SAEG 均未完成。案例分析显示，EAGS 能处理不劫持控制流而通过改写关键局部变量实现状态操纵的 p0wn3d_2 案例，并能在经典 ret2libc 案例中将地址泄露转化为约束可满足性问题而非模拟完整 I/O 过程。",
    "contribution": "主要贡献：提出可验证利用原语 VEP 与 ESM，提升复杂漏洞场景中多层利用路径的分析能力；提出基于 ESM 的 EAG 模型，支持分段利用并以 SVEAA 弥补传统 AEG 结果细节不足的问题；实现原型 EAGS 并通过与主流工具在统一数据集上的对比实验证明其准确率与效率优势。局限：尽管统一接口使新增 VEP 无需修改 ESM，但编码特定技术的语义仍需人工努力，且跨架构、ABI、库与缓解机制时成本较高；不支持的利用技术可能造成漏报（false-negative）。未来工作将探索更复杂漏洞环境并引入深度学习以增强对未知漏洞模式的适应性。\n---\nDOI: 10.1016/j.cose.2026.105140",
