    "direction": "人工智能",
    "summary": "论文提出 CL-Rank，通过任务间低秩子空间相似度自适应调整各层 LoRA 的秩，在持续学习中兼顾减少旧任务遗忘与适应新任务。",
    "question": "LLM 按顺序学习多个任务时容易发生灾难性遗忘；固定所有层和任务的 LoRA 秩又忽略了不同层的异质性，难以同时保持旧知识和学习新知识。作者因此把稳定性—可塑性权衡转化为低秩更新子空间之间的干扰控制问题，并希望在不访问旧任务数据的条件下完成参数高效的持续学习。",
    "method": "CL-Rank 为第一个任务使用固定低秩 LoRA，为后续任务从秩 1 的增量 LoRA 开始，并冻结历史 LoRA。训练期间对当前任务与历史任务的 LoRA 做逐层 SVD，利用投影度量构造归一化的子空间相似度；当相似度低于正交阈值时增加当前层秩，否则保持秩以减少干扰。方法还可对非正交更新施加正交子空间投影，并通过更新间隔控制相似度测量频率，从而把额外 SVD 成本限制在低秩矩阵上。",
    "experiments": "实验使用 T5-large、T5-base 和 Llama-2-7b，在五数据集标准持续学习基准、包含 15 个数据集的长任务序列，以及 GSM8K 和 MATH 数学基准上评估。T5-large 标准基准三种任务顺序的平均准确率中，CL-Rank 含正交投影为 76.8%，O-LoRA 为 75.4%；Llama-2-7b 长任务序列中，CL-Rank 平均为 73.4%，O-LoRA 为 71.2%，平均/最大顺序性能差异为 4.953%/6.171%。在 15 任务设置中，CL-Rank LoRA 存储为 78.8 MB，O-LoRA 为 121.5 MB，但虚拟内存为 78.6 GB 对 76.4 GB；Llama-2-7b 上 15 任务运行时间为 4:27:45，对照 O-LoRA 为 2:46:39。GSM8K 与 MATH 的顺序实验也显示 CL-Rank 相比 O-LoRA 对早期任务遗忘更少、对后续任务适应更好。",
    "contribution": "贡献是提出逐层、基于子空间相似度的 LoRA 秩增长规则，并在 T5 与 Llama-2、自然语言和数学持续学习任务上验证其稳定性—可塑性收益；实验还系统分析了任务顺序、阈值、更新间隔、初始秩和样本量。局限是方法针对 LoRA 持续微调场景，不能直接推广到大规模预训练；SVD 和历史子空间交互带来明显运行时间与虚拟内存开销，长任务序列和更大模型上的扩展性仍需进一步验证。\n---\nDOI: 10.1007/s10994-026-07145-4",
