    "title": "MS-Workset: A novel worker misbehavior dataset for workers’ behavior tracking in mobile crowdsensing environment",
    "authors": "Ahmed Abduljawad, Hanane Lamaazi, Muhusina Ismail, Omar EL Harrouss, Saed Alrabaee, Elarbi Badidi",
    "journal": "Computers & Security",
    "year": "2026",
    "published": "2026-09-05",
    "contentState": "complete",
    "contentNote": "已依据出版社正式版全文整理",
    "doi": "10.1016/j.cose.2026.105136",
    "arxiv": "",
    "pdf": "papers/COSE_2026_MSWorkset.pdf",
    "link": "https://doi.org/10.1016/j.cose.2026.105136",
    "direction": "信息安全",
    "summary": "本文提出移动群智感知场景专用的工人不当行为数据集 MS-Workset，建模多账号、低质量上报与 GPS 伪造三类行为，规则与机器学习检测精度均超过 98%。",
    "question": "移动群智感知（MCS）依赖大量异构且未必可信的工人收集数据，工人不当行为（如多账号攻击、提交低质量或伪造数据、GPS 位置造假）会降低系统性能与可信度，并导致不公平激励分配；区分恶意攻击与传感器故障等无意错误尤为困难。已有检测工作受限于缺乏真实 MCS 不当行为数据集与基准，现有合成数据仅聚焦任务分配、信誉或数据一致性，未建模真实工人行为，缺乏不当行为标注的真值。为此作者提出两个研究问题：如何以结构化数据集真实模拟并表征各类工人不当行为，以及如何在多样化不当行为下识别工人可信度同时避免误伤可信工人。",
    "method": "论文将不当行为分为认知型（低质量工人、多账号对抗）、设备型（故障传感器、GPS Spoofing）与任务执行结果导向型（重放攻击、Target Chaser、合谋伪造任务）三类，并构建可控仿真模型 MS-Workset，围绕多账号、低质量上报与 GPS 伪造三个独立场景生成数据。系统以任务与工人的几何空间交互为基础（Haversine 距离、可达范围约束），以账户为身份粒度建模信誉评分（基于上报方差、报告质量梯度、完成子任务数），对违规账户降分并黑名单化、撤销既往上报。仿真记录账户 ID、任务 ID、坐标及行为指标，形成统一结构的 CSV 输出（Phase 1），随后进入基于规则的检测模块（Phase 2）验证，并进一步用监督机器学习模型（Random Forest、XGBoost、Gradient Boosting、SVM、MLP、Logistic Regression）交叉验证行为特征的可分性。",
    "experiments": "仿真区域为阿联酋 Al-Ain（纬度 24.07–24.35、经度 55.55–55.90），任务 T 与工人 W 取 500/1000/1500，多账号场景迭代 100000 次、低质量场景 1000 次；初始信誉 r0=0.3、最低信誉 rmin=0.1、最大可达距离 dmax=5 km、方差权重 0.75、位移阈值 L=15。基于规则检测（Table 4）中多账号场景准确率 98.6%、精确率 99.2%、召回率 99%、F1 99.1%；低质量场景准确率 97.07%、精确率 100%、召回率 89.37%、F1 94.39%；GPS 伪造场景准确率 98.80%、精确率 100%、召回率 96.03%、F1 97.97%，且能保持正常上报分布的\"钟形\"形态不被打乱。机器学习验证（Table 5）中多账号场景 XGBoost 交叉验证准确率 0.9662、测试准确率 0.9769，Random Forest 交叉验证 0.9654；低质量场景三种集成模型测试准确率均达 0.9996、精确率 1.0；GPS 场景 Gradient Boosting 测试准确率 0.9988。资源开销上，攻击场景执行时间多账号 120.1 秒、低质量 78.69 秒、GPS 伪造最快 6.66 秒；系统规模增大时多账号检测准确率下降，其余场景随任务数变化稳定、随工人数增多略降。",
    "contribution": "贡献包括：提出首个面向 MCS 工人不当行为的受控仿真模型与结构化数据集 MS-Workset（公开于 GitHub: https://github.com/HananeLAMAAZI/SUREPlus-24.git），覆盖身份滥用（多账号）、数据操纵（低质量/伪造报告）与上下文操纵（GPS 伪造）三大场景；提供基于规则的检测框架与可信/不可信分类机制，结合信誉反馈防止不可信工人被重复选中；并通过规则与机器学习两类算法在多个规模组合下系统验证了检测准确性、稳定性与公平性。局限方面，当前仅建模单一不当行为场景，未覆盖合谋对手与大规模 Sybil 攻击；未来将扩展上下文感知行为模型与更多对抗场景，并尝试替代性信任评估与检测技术。\n---\nDOI: 10.1016/j.cose.2026.105136",
