    "pdf": "papers/TKDE_2026_DynamicAnchorHypergraphEnsemble.pdf",
    "link": "https://doi.org/10.1109/tkde.2026.3710223",
    "direction": "人工智能",
    "summary": "本文提出 DREAM，一种仅利用基聚类结果、通过动态锚点学习、超图重构与局部共识对齐实现一步式输出的集成聚类方法，避免了 n×n 共协矩阵的高复杂度与后处理步骤，精度显著优于 17 个代表方法。",
    "question": "集成聚类融合多个基聚类结果以获得更稳健的共识划分，且只使用决策级输出、不访问原始特征，因此天然具备特征级隐私保护优势，适用于跨机构医疗分析、金融风险画像等隐私敏感场景。然而，主流方法基于 n×n 的共协（CA）矩阵，带来 O(n²) 乃至 O(n³) 的时间复杂度，难以扩展到大规模数据；已有锚点类方法虽缓解了规模问题，却普遍采用 K-means 等静态锚点选择策略、需要后处理（如对锚相似矩阵再跑 K-means）才能得到最终标签，部分方法还依赖原始特征选锚，损害了集成聚类的隐私优势，并造成锚点不灵活、锚相似矩阵质量低、精度受限。作者据此提炼出三个挑战：提高基聚类结果可靠性（C1）、仅凭基聚类结果动态选锚并构造高质量锚相似矩阵（C2）、在一体化一步式范式中利用基聚类蕴含的局部共识信息（C3）。本文是作者 IJCAI-25 会议工作 YACHT 的扩展，将原先的两阶段框架重构为一步式重建-分配模型。",
    "method": "DREAM 首先把 m 个基聚类结果转化为超图（节点为样本、每条超边对应一个基簇），再对超边两两计算 Jaccard 相似度并归一化为概率转移矩阵，用 d 阶随机游走传播得到超边间的高阶关系矩阵，据此按相似度阈值 α 合并超边，得到更稳定可靠的增强超图 H。随后引入映射矩阵 P 过滤冗余超边信息，通过矩阵分解重构目标 ∥PᵀH−AZ∥²_F 联合优化锚点矩阵 A 与锚相似矩阵 Z（k×n）；与固定锚点不同，A、Z 在优化中被动态更新，锚点是可学习的潜在代表而非静态样本或质心。接着从基聚类中抽取“共识基簇”（样本间超图隶属列一致且所含样本数不少于 2），按包含样本数排序取前 k 个构造局部共识指示矩阵 Zc，通过最大化 Z 与 Zc 的逐元素一致性（Hadamard 积项）把局部共识信息嵌入锚相似矩阵。最后引入质心矩阵 C 与离散分配矩阵 F，在目标中加入 ∥Z−CF∥²_F 项，使 F 具有严格聚类解释、可直接产出最终共识标签，无需任何后处理；相比 YACHT，DREAM 直接耦合 Z 与 F 并对 Z 本身做对齐，省去中间标签空间的反馈环节。目标函数采用交替优化求解（P、A、C 用 SVD 闭式更新，Z 用增广拉格朗日乘子法 ALM 更新，F 按最近质心指派），单步主导复杂度中与样本相关的项随 n 线性增长，整体空间复杂度 O(sn+s²)，避免 CA 矩阵方法的 O(n²) 开销。",
    "experiments": "实验在 1 个合成数据集（百万规模 Blobs-Rings）和 9 个真实数据集上进行，多数数据集通过运行 K-means 100 次生成基聚类，集成规模设为 20 并做 10 次重复实验取均值；实现环境为 MATLAB R2024b（AMD 7763 64 核 CPU、128 GB 内存），代码开源在 GitHub。与 17 个代表方法对比，覆盖 SOTA 集成方法（ECCMS、CEAM、CESHL、TRCE、DREC、ECPCS-MC、GPEC、YACHT）、快速集成方法（LWGP、USENC、SEC、PTA-AL/CL、PTGP、CEHM、FSEC）及一步式多视图聚类方法 UDBGL，用 ACC、ARI、NMI、Purity 四个指标评价。结果显示：在 ACC 上 DREAM 相对基聚类平均性能平均提升 10.43%，在大多数数据集上取得最优，且在 Blobs-Rings、Covtype 等大规模数据上优势明显；Friedman 检验中 DREAM 在四项指标上的平均秩均最低。相比之下，CA 矩阵类方法（ECCMS、GPEC、CEAM）在大规模数据上出现运行时间过长或内存溢出，DREC、CESHL 等样本-簇矩阵/超图方法未在任何数据集上取得最优。DREAM 在多数数据集的多数指标上优于会议版 YACHT，少数数据集有下降，作者归因于局部共识源于基聚类、其成员关系正确性无法完全保证。参数研究表明 k′（锚点数 k=c+k′）与阈值 α 上 DREAM 总体不敏感，推荐 k′=0 或 −1 且 α>0.98；随机游走阶数 d 在 {5,10,15,20,25} 上总体稳定，支持默认 d=10。运行时间对比中 USENC、FSEC 最快（锚点固定不变），DREAM 因动态更新锚点略慢但整体略快于 CEHM，精度明显更高。消融实验显示：去掉超图增强导致明显性能下降，去掉一步分配项 ∥Z−CF∥²_F 的变体总体劣于完整模型，说明超图质量与一步式设计均不可或缺；而去掉映射矩阵 P 或局部共识对齐项下降较小、个别数据集上略有提升。集成规模 m 增大并不严格提升精度（新增基聚类未经筛选），但最小集成规模通常性能最低，运行时间随 m 增加而上升。",
    "contribution": "主要贡献：提出特征无关（仅依赖基聚类结果）、动态锚点的一步式超图集成聚类方法 DREAM，将相似矩阵维度由 n×n 压缩为 k×n，规避 CA 矩阵的规模瓶颈且无需后处理；设计基于超边间高阶随机游走传播的超图增强策略，提升初始超图可靠性；提出局部共识信息对齐机制，使锚相似矩阵保留基聚类间的共识结构，并把离散分配直接纳入统一优化目标，相较会议版 YACHT 减少中间标签空间反馈与信息损失。局限与展望：动态锚点更新带来额外运行时间，因此 DREAM 不是最快的集成聚类方法；锚点数 k 与相似度阈值 α 仍需人工设定（当前用网格搜索），超边较多时 O(s²n) 与 O(ds³) 的 s 依赖项可能成为瓶颈；作者计划未来研究全无监督场景下自动确定锚点数与阈值，以及流式/增量式扩展，使新样本或新基聚类到来时能更高效地更新增强超图与动态锚点。\n---\nDOI: 10.1109/tkde.2026.3710223",
