    "summary": "论文联合优化无人机发射功率和飞行位置，在恶意检测器存在噪声不确定性的条件下，提高隐蔽通信的单位能耗吞吐量。",
    "question": "无人机空地链路容易被窃听或检测，同时机载能源有限；传统加密会增加计算和能耗，单独设计功率或位置又难以同时满足隐蔽性、可靠性和吞吐需求。论文关注无人机向合法地面接收端秘密传输时，如何在检测风险和能量消耗之间取得更优折中。",
    "method": "作者以可实现隐蔽吞吐量与能耗之比定义隐蔽能效，建立考虑检测器噪声不确定性的最小检测错误概率，并将隐蔽约束、吞吐约束和功率限制纳入三维联合优化。通过系统几何关系和指标单调性分析，原问题被化为只需搜索飞行角度的一维问题，同时推导给定飞行角度下的最优距离和发射功率，从而可用向量化计算高效求解。",
    "experiments": "数值实验验证了检测错误概率和最优位置、功率的理论推导，并考察最小吞吐要求、检测器位置和系统几何等参数。联合设计相比固定位置、固定功率或分步优化方案，在隐蔽吞吐量和单位能耗表现上更有优势；当最低吞吐要求增大时，可用功率和隐蔽性约束收紧，隐蔽能效相应下降，说明吞吐可靠性与隐蔽节能之间存在明确折中。",
    "contribution": "论文给出了无人机隐蔽通信中功率—位置联合设计的理论化简和高效求解方法，避免直接求解原始三维非凸问题。局限在于模型主要采用静态几何、单一合法接收端和单一恶意检测器假设，未充分考虑多无人机、移动用户、动态信道、障碍物和实际飞行能耗；真实空地实验及更复杂检测器下的鲁棒性仍需研究。\n---\nDOI: 10.1109/TDSC.2026.3714209",
