    "summary": "MKFGOD 融合多个核函数形成模糊关系，再以多核模糊邻域密度衡量样本偏离程度，从而比单核和传统异常检测器更全面地识别不确定离群点。",
    "question": "模糊信息粒化能够表达数据不确定性，适合无标签异常检测，但已有核化模糊离群检测器多依赖单一核函数，容易只捕捉某一种数据结构并产生检测偏差。不同核函数可以从不同相似性视角提取信息，如何融合这些核关系并形成稳定的离群度量，是提升复杂数据检测效果的关键。",
    "method": "MKFGOD 先用多个核函数从数据构造模糊关系矩阵，再通过多种融合策略得到多核模糊关系。基于融合关系，算法定义多核模糊 k 近邻和多核模糊邻域密度，以样本邻域密度偏离程度计算离群度；框架利用模糊粒化保留不确定结构，同时通过多核融合减少单一核函数对数据分布的偏置。",
    "experiments": "作者在多个公开数据集上将 MKFGOD 与单核检测器及主流离群检测算法比较。实验显示，融合多个核函数后，方法在检测性能上整体显著优于单核和传统基线，尤其能更好处理复杂分布、边界样本和不同类型的异常。结果支持多核信息融合对模糊离群检测的有效性。",
    "contribution": "论文将多核信息融合、模糊关系、模糊近邻和信息粒化结合，形成了可解释的多视角离群度量。局限在于核函数选择、融合策略和邻域参数会影响结果，多核计算也可能增加时间与内存开销；大规模流式数据、自动核选择、概念漂移和带标签半监督异常检测仍需进一步研究。\n---\nDOI: 10.1109/TKDE.2026.3708765",
