    "pdf": "papers/TDSC_2026_DRAWAdjustableWatermarking.pdf",
    "link": "https://doi.org/10.1109/TDSC.2026.3714391",
    "direction": "信息隐藏与数字水印",
    "summary": "DRAW 将不同失真对应的水印鲁棒特征分离训练，再用 Transformer 解码器统一提取，使训练完成后的各类鲁棒性能够独立调节。",
    "question": "深度水印通常把 JPEG 压缩、噪声、模糊等失真放在同一个训练噪声层中，因而能获得综合鲁棒性，但各种鲁棒性彼此耦合，部署后难以按场景独立增强或削弱。论文希望在保持总体抗扰性的同时，让使用者根据应用需要灵活调整不同失真下的保护强度，并改善透明性—鲁棒性折中。",
    "method": "DRAW 分两阶段训练。第一阶段随机生成多个相互正交的掩码，把不同鲁棒特征分配到不同嵌入区域，并针对单一失真并行训练多个水印网络；第二阶段固定已训练的特征嵌入网络，训练基于 Transformer 的解码器，以适配多个水印区域和失真类型。系统通过加权不同区域的嵌入强度调节鲁棒性，并加入频域损失改善视觉透明性。",
    "experiments": "实验比较了现有先进框架，并在多种失真下测试提取准确率、图像质量和可调节性。各类失真下的平均鲁棒性约为 98%±0.5%，引入改进解码器后，提取准确率相较 MBRS 提升约 4%；消融结果表明，单独解码器难以同时保留所有区域特征，而分离训练和频域损失能在强鲁棒性与较少可见伪影之间取得更好平衡。",
    "contribution": "论文提出了可独立调节多种鲁棒性的深度水印框架，解决传统联合噪声训练后鲁棒性难以解耦的问题，并验证了较强泛化能力。局限是当前鲁棒性分区依赖固定的方形掩码，掩码位置和大小仍需人工设定；未来需研究自适应区域划分、自动选择鲁棒性强度，以及几何变换和更强去水印攻击下的稳定性。\n---\nDOI: 10.1109/TDSC.2026.3714391",
