    "question": "分布式学习把数据留在本地，但共享梯度仍可能泄露训练样本，聚合模型可能遭受成员推断，恶意客户端还可能篡改训练过程。现有方案往往只解决其中一个层面的安全问题：安全聚合带来加密计算成本，差分隐私在密文域中的非线性操作昂贵，恶意韧性又需要额外的正确性验证。论文希望用一个可部署的框架同时覆盖三类风险。",
    "method": "Fortress 采用双服务器布尔秘密共享完成安全聚合，使单个服务器不能恢复客户端梯度；在秘密份额上直接加入差分隐私噪声，并用多项式近似避免加密域中的昂贵非线性运算；同时使用轻量级转录验证检查客户端和服务器是否遵守协议，以识别训练级恶意操作。三个机制共同形成从梯度、模型到训练流程的多层防护。",
