    "contribution": "论文的核心贡献是把梯度级隐私、模型级推断防护和训练级恶意韧性进行协同设计，并以秘密份额直接加噪和轻量转录验证缓解组合开销。局限在于双服务器信任假设、差分隐私预算和多项式近似会影响安全—精度折中；更大规模参与者、强串谋服务器、异步训练和非凸复杂模型下的性能仍需研究。\n---\nDOI: 10.1109/TDSC.2026.3715844",
