    "direction": "隐私保护与机器学习安全",
    "summary": "论文指出，当训练集中存在与待删除样本相似的样本时，许多机器遗忘方法只删除目标样本本身，未能真正消除其对模型的影响，并系统评估了这一缺陷。",
    "question": "机器遗忘的目标不是简单从数据集中删掉一条记录，而是让模型不再保留该样本带来的影响。现实数据中，同一用户可能提交多个相似问题、评论或图像变体；只遗忘其中一个样本，模型仍可能通过相似样本保留相关信息。论文希望检验现有遗忘方法是否符合“消除影响”的原始定义，并探索如何提升相似样本场景下的遗忘效果。",
    "method": "作者构造四个包含相似样本关系的数据集，分别考察图像和语言模型在目标样本、训练集相似样本及相近测试样本下的行为。研究比较多种机器遗忘方法与从头重训基线，分析模型输出、表示和相似样本残留影响；在此基础上引入鲁棒训练等增强策略，测试其能否减少相似样本造成的遗忘失败。",
    "experiments": "四个数据集的实验显示，多数现有方法在训练集中存在相似样本时，仍会保留目标样本相关影响，甚至从头重训也不一定达到理想的目标遗忘效果。增强策略能够在多个设置中持续改善遗忘表现；在语言和图像任务的效用保持方面，增强后的方法与未增强方案总体相当，说明改善遗忘不必然带来同等程度的正常能力损失。",
    "contribution": "论文把“删除样本”和“消除样本影响”区分开来，系统揭示了相似样本对机器遗忘评估的影响，并提供了更贴近真实删除请求的测试框架。局限在于相似样本数据集仍是人工构造或受控场景，语言和图像模型范围有限；如何定义可证明的影响消除、处理大规模近邻数据以及应对多模态和连续数据删除仍需进一步研究。\n---\nDOI: 10.1109/TDSC.2026.3714774",
