    "summary": "GP-PI-K 将解析物理模型或不完美模拟器融入高斯过程核函数，以改善动力系统外推。",
    "question": "高斯过程能提供不确定性估计并吸收先验知识，但在训练区域外通常外推较差。仅把先验模型放入均值函数，可能无法充分影响相似性结构。研究希望保留高斯过程的不确定性优势，同时改善一步和多步预测。",
