    "summary": "QKS-ME 是一种抗量子可搜索匹配加密方案，在双边访问控制下支持先按关键词筛选、后按需解密，并避免失败搜索向云端或未授权接收者泄露原因和结构信息。",
    "question": "云数据市场需要在互不信任的交易方之间共享金融、基因或威胁情报等敏感数据，同时满足机密性、真实性、访问控制和监管要求。现有方案通常只能覆盖其中部分需求，尤其难以同时支持双边授权、关键词检索、按需解密和失败访问隐私；面对后量子攻击者时，传统密码结构也存在长期风险。",
    "method": "QKS-ME 建立在格困难问题之上，将关键词检索、匹配加密、双边访问控制和按需解密组合起来。云端可以先对密文执行关键词过滤，但只有在双方授权条件满足时才允许解密；未成功的检索或解密不会泄露明文、关键词或底层访问结构。论文形式化证明了选择明文不可区分性、选择消息存在不可伪造性和陷门不可链接性。",
    "experiments": "实验比较加密、解密、陷门生成和搜索开销。QKS-ME 通过省去相关方案中的零知识证明，取得更短的密文和更小的陷门；当安全参数增大到 512 时，加密开销仍低于 500 秒，搜索阶段保持毫秒级响应，并在多种参数设置下具有较低的陷门生成与搜索时间。与功能较少的方案相比，方案用可接受的密文长度换取了双边访问控制和按需解密。",
    "contribution": "论文在格密码基础上统一了双边授权、关键词搜索、失败隐私和按需解密，并给出安全证明与实验评估。局限在于格密码在高安全参数下的加密成本仍然较高，密文和索引规模可能随数据和关键词数量增长；大规模动态市场、访问撤销、关键词更新、恶意云服务和更复杂查询模式仍需进一步研究。\n---\nDOI: 10.1109/TDSC.2026.3715531",
