    "summary": "论文提出 Symbolic Neural Generators（SNG）：先从少量样本和背景知识中学习可验证的符号约束，再让神经生成器在约束条件下产生新实例。作者用这一框架生成潜在药物分子，使输出同时具备较复杂的分布建模能力和可检查的化学/生物约束。",
    "question": "早期药物设计常只有少量已知抑制剂，目标位点、有效分子集合和可合成性约束又可能并不完整。纯符号方法容易难以表达分子分布，纯神经或 LLM 生成则可能产生无法验证、偏离任务条件的分子；少样本微调也不足以可靠地学习生成分布。因此需要把符号学习的可解释、可验证约束与神经模型的生成能力结合起来。",
    "method": "SNG 用 base poset 表示符号假设 H，用与 H 对应的 fibre poset 表示满足约束的神经样本集合 X，并把输出定义为二元组 (H, X)。具体的 GenMol 将分子量、合成步数、binding affinity 等因子写成区间型超矩形，使用受限 ILP/贪心搜索挑选高后验假设，再以 GPT-4o 作为生成器进行 rejection sampling；每个候选分子都要通过符号谓词检查，生成集合的有效性由形式化语义保证。",
    "experiments": "在 chess endgame 的 WFW 稀有事件上，加入符号理论后，GPT-4o 在 0-shot 条件下由第 1 轮的 17 个有效实例提升到第 2 轮的 30 个；5-shot 条件下由 23 个提升到 30 个，而无符号理论的 0-shot 第 5 轮仍为 0 个。JAK2/DRD2 基准上 GenMol 的 binding affinity 均值分别为 8.59（0.23）和 7.53（0.47）：JAK2 高于 LMLF++ 的 7.74（0.30），DRD2 略低于 LMLF++ 的 7.66（0.29）但与其处于同一水平；生成分子的 Tanimoto coefficient 约为 0.14 和 0.13。DBH 仅给定 5 个已知抑制剂时，专家认为多枚 in-the-box 与 out-of-the-box 分子具有潜力且可合成。",
    "contribution": "主要贡献是提出 SNG 这一符号学习—神经生成范式，并用 fiber-poset 给出候选符号假设与生成实例的语义和正确性框架；GenMol 还展示了极少样本下的分子先导发现价值。局限包括当前搜索是贪心的、不回溯固定假设下的样本选择，生成器依赖低效的 rejection sampling，0/1 式生成效率评分会过度剪枝；DBH 结果主要来自 docking 与专家判断，尚未替代湿实验验证，且 LLM 的训练数据暴露和参数设置可能影响基准表现。\n---\nDOI: 10.1007/s10994-026-07136-5",
