    "question": "机械设备在变载荷、冲击和强干扰环境下可能磨损、开裂或断裂，造成停机甚至事故。接触式诊断虽然精确，却受极端环境部署限制。非接触传感可降低物理连接风险，但多源数据和复杂工况增加了诊断建模难度。",
