    "authors": "Wenjing Chen, Jie Cui, Wenjie Huang, Jing Zhang, Lu Wei, Geyong Min",
    "journal": "IEEE Transactions on Dependable and Secure Computing",
    "year": "2026",
    "published": "2026-07-03",
