    "method": "LMIRA 首先利用边缘计算和 Transformer 预测下一个路侧单元域的交易到达率与区块大小，并据此进行负载调节。随后建立多指标车辆数据共享评价框架，从多个维度衡量共享信息质量和信誉；最后设计跨域认证机制，在保护车辆身份隐私的同时验证数据与参与方的可信性。系统在 Hyperledger Fabric、SUMO 和 Raspberry Pi 4B 实体平台上实现。",
    "experiments": "基于真实车辆轨迹的仿真和实体平台实验表明，LMIRA 相比现有方案吞吐量至少提高 3.6 倍，延迟稳定低于 0.6 秒，交易提交失败率至少降低 43.2%。结果显示，边缘预测和多指标信誉机制能改善跨域数据共享容量，认证流程也能在车辆移动和管理域切换时保持较好的适用性。",
    "contribution": "论文将负载预测、信誉评估和跨域认证统一到面向车联网的区块链框架中，并同时进行仿真和树莓派实测。局限在于实验平台、交通轨迹和域规模仍有限，Transformer 预测误差、车辆恶意串谋、网络断连和跨链互操作可能影响实际效果；更大规模车路云协同与长期移动场景仍需验证。\n---\nDOI: 10.1109/TDSC.2026.3715693",
