    "summary": "论文分析团队协作工作区中第三方插件与宿主 API 的权限边界，提出自动化测试工具 TAI，发现插件可能绕过管理员设定的权限隔离并造成权限提升。",
    "question": "Google Workspace、Microsoft OneDrive 等团队工作区允许第三方插件访问和管理共享资源。多用户协作、管理员权限和插件权限交叠后，权限系统不再像单用户环境那样清晰，插件可能通过跨用户、跨资源或跨 API 的组合交互超出授权范围。已有测试通常只检查单个权限声明，难以系统探索所有交互路径，论文希望揭示这一生态中的权限提升风险。",
    "method": "作者先分析团队工作区的访问控制机制，抽象出可能导致权限提升的三类风险和权限相关交互，再开发 TAI 自动遍历、构造和执行权限测试。工具围绕插件、用户角色、资源类型和宿主 API 组合测试，比较管理员设定与实际可达权限，从而定位越权读取、修改或操作共享资源的路径，并对平台和第三方开发者暴露的权限边界进行系统评估。",
    "experiments": "研究在主流团队工作区生态中运行 TAI，对潜在权限交互进行系统检查，共识别出 41 个存在问题的交互。结果表明，权限提升风险并非个别插件实现错误，而是可能广泛存在于插件与工作区权限模型的组合边界；论文据此提醒平台方加强跨主体权限隔离，并建议开发者减少对隐式继承权限的依赖。",
    "contribution": "论文贡献了面向团队工作区插件权限的风险分类、自动化测试工具 TAI 和生态级实证结果，补充了传统单用户权限测试的盲区。局限在于不同平台 API、版本和租户配置可能影响可复现性，已发现交互也不等同于所有真实攻击路径；后续需要研究权限策略修复、跨平台泛化、插件更新后的持续测试和真实影响验证。\n---\nDOI: 10.1109/TDSC.2026.3715679",
