    "experiments": "评估覆盖 16 部智能手机、2 台平板、4 台笔记本和 3 台智能音箱，共 25 台商用设备；每台设备每条命令进行 100 次尝试。平均注入成功率为 95.01%，攻击声压约 35 dB，且在具备录音接口的设备上保持较好的 PESQ 语音质量。结果表明，攻击能够绕过多种说话人验证系统，并在遮挡、环境噪声和部分设备差异下保持有效，但不同扬声器结构会造成成功率明显波动。",
    "contribution": "论文揭示了由磁驱动内置扬声器形成的硬件攻击面，完成从机理、仿真到原型和跨设备实测的系统分析，并提醒语音助手防护不能只依赖软件和麦克风侧过滤。局限在于效果依赖特定设备的扬声器、电磁耦合和安装距离，现有防御对全部攻击变体的覆盖仍有限；真实部署还需研究更广泛的设备、姿态、封装结构和硬件级检测方案。\n---\nDOI: 10.1109/TDSC.2026.3708889",
