    "summary": "ADGC 从两个特征视角构造自适应上下圆锥信息粒，通过动态阈值、噪声过滤和中心加权更新，提高复杂异构数据上的聚类准确性和泛化能力。",
    "question": "传统聚类依赖固定距离度量和单一特征视角，在不规则形状、密度不均、重叠和噪声数据上容易受参数影响。经典密度、划分和图聚类方法也常需要人工设定阈值或承担较高计算代价。论文希望利用信息粒度表示数据结构，在减少噪声的同时保留多视角关联，并自动确定更适合数据的聚类关系。",
    "method": "ADGC 根据属性分位数熵构造数据驱动的优势阈值，从两个特征视角生成上、下圆锥信息粒，并依据距离增长趋势自适应估计半径。算法用全局双向粒中心性和空间离散约束选择初始中心，计算每个双向粒的覆盖强度和权重，形成并融合共现相似矩阵，再通过中心加权机制迭代更新聚类分配，从而兼顾关联性、噪声过滤和多视角信息。",
    "experiments": "作者在多种复杂数据集上与主流粒计算聚类算法比较。结果显示，ADGC 能较准确地识别不规则、重叠和密度不均的簇，在聚类质量指标上整体优于对比方法；双视角粒结构和动态半径尤其有助于减少单一视角或固定阈值造成的误分，说明算法对异构数据具有较好的适应性。",
    "contribution": "论文提出了双视角自适应圆锥信息粒、数据驱动阈值和中心加权聚类流程，将粒计算的结构表达与噪声鲁棒性结合起来。局限在于多视角粒构造和相似矩阵融合会增加计算成本，参数和特征尺度仍可能影响大规模数据表现；动态数据、非欧空间、缺失特征及自动确定簇数等问题还需进一步研究。\n---\nDOI: 10.1109/TKDE.2026.3708513",
