    "title": "Refunded but rewarded: The double dip attack on cashback reward engines",
    "authors": "S M Zia Ur Rashid, Suman Rath",
    "journal": "Computers & Security",
    "year": "2026",
    "published": "2026-08-29",
    "contentState": "complete",
