    "link": "https://doi.org/10.1016/j.cose.2026.105129",
    "direction": "信息安全",
    "summary": "“双重获利”攻击是在购买并兑换返现后退款，却因奖励引擎缺少及时、按交易关联的回扣而保留奖励；论文将这一逻辑缺陷形式化为状态机不变量并提出防御算法。",
    "question": "返现奖励是叠加在支付清算之上的软货币，生命周期应跟随交易授权、结算、退款、部分退款和兑换同步，但奖励系统常被当作营销功能而非安全关键状态机。若用户先获得并兑换奖励，再把商品全额退回，而账本不调整，便可能零净支出仍保留奖励，形成可重复的业务逻辑滥用。现有退货和促销研究多讨论经济或检测问题，较少明确建模奖励账本的完整性。",
    "method": "论文将用户、发行方、商户和支付网络建模为实体，把交易与奖励账本建模为状态机，并定义 Reward Integrity 与 Refund Reward Consistency 两个不变量。作者提出三级漏洞分类：发行方 A 完全不回扣；发行方 B 在账单结算后到达的退款不回扣；发行方 F 立即让奖励可用但延迟批量回扣，造成时间窗口；发行方 C/D/E 对负余额和按比例回扣更稳健。防御伪算法按交易关联奖励、对全额/部分退款做比例回扣、允许负奖励余额并用未来奖励抵销，同时在账单周期内协调待处理退款，并给出带假设的半形式正确性论证。",
    "experiments": "六个真实生产发行方账户的购买—兑换—退款流程显示三类行为。发行方 A 可确定性复现双重返现；发行方 B 的账单结算前退款会调整，但测试的结算后退款（包括延迟多个账期和部分退款）未调整；发行方 F 会生成负奖励记录，却因奖励即时可兑换而存在提取窗口；C、D、E 对测试流程实行持续负余额和比例回扣，未被攻击流程绕过。论文还说明这些现象属于奖励完整性违反，而非估计行业普遍率或攻击者实际盈利。",
    "contribution": "贡献是把返现退款滥用从“促销问题”提升为业务逻辑安全问题，给出可验证的不变量、漏洞分类、生产案例和可实现的防御流程；发行方 A 的漏洞还通过私有漏洞赏金渠道报告并获确认。局限是样本只有六个作者持有账户、选择非随机，缺少后端和风控可见性，未系统覆盖商户、退款金额、兑换渠道和所有时间偏移，也未测量净盈利或独立复现。正确性论证依赖交易可分离和可校准的宽限期假设。\nDOI: 10.1016/j.cose.2026.105129",
    "sample": false,
