    "method": "借鉴人体免疫系统区分“自我/非我”的自适应分布式机制，构建包含四类能力的内生主动防御范式：信任评估、动态防御、自愈（self-healing）与免疫记忆；进一步引入动态阈值机制，使判定边界随运行状态与未知攻击自适应。防御策略模块负责存储已知/未知攻击特征、对目标行为作出判断并下发策略；检测到异常后终止行为并按最小权限重置权限。",
    "experiments": "实验达到 TPR 97.45%、FPR 低至 2.81%；相对 NeuroShield、SAF-ADM、IIMDA、FTASH 等对比模型，检测准确率约提升 3%–10%，FPR 降低约 2%–3%；对未知攻击的检测准确率提升约 2%–15%。消融显示移除防御策略后 TPR 降至 71.38%、FPR 升至 19.93%；损伤评估指标 PDI 上 DMBM 最低（0.26），优于 NeuroShield（0.41）、SAF-ADM（0.57）与 FTASH（0.39）。",
    "contribution": "- 贡献一：把免疫“自我/非我”机制转化为内生主动防御模型，整合信任、动态防御、自愈与免疫记忆于一体。\n- 贡献二：动态阈值机制提升对运行变化与未知攻击的适应性；防御策略与免疫记忆显著降低系统损伤（PDI）。\n- 局限：实验主要面向特定仿真/数据集环境；免疫记忆规模、分布式扩展与真实大规模网络的部署验证有待后续工作。\n---\nDOI: 10.1016/j.cose.2026.105132",
