    "question": "科学数据采集速度持续超过存储与分析能力，体素表征越来越不可行。隐式神经表征（INR）用坐标网络充当数据代理，存储与计算随网络复杂度而非数据维度增长，但小 INR 难以忠实表征多尺度结构、高频信息与精细纹理——而这些在科学测量中占比很大。",
    "method": "两条设计原则：一是在能更好解耦与去相关信息的域中操作以改进率失真；二是直接针对小 INR 在参数预算下无法捕获全频谱信息的根本局限。实现上，WIEN-INR 在多分辨率小波域工作，用多个子网络分别建模不同时间–频率内容，并用一个紧凑的增强网络（enhancement network）恢复细微细节；模块化设计保持训练效率与低存储成本。",
