    "direction": "信息安全",
    "summary": "论文设计并评估了一款无需屏幕、无需指导者且可单人完成的钓鱼识别配对纸牌游戏，结果表明它能在游戏后两天仍显著提升参与者区分钓鱼与合法邮件的能力。",
    "question": "钓鱼攻击持续利用用户知识和安全意识不足，而许多安全教育工具依赖屏幕，可能进一步加重数字疲劳。现有措施也常以讲授为中心，较少支持自我引导和主动解决问题。作者因此希望开发一种熟悉、低成本、短时、面向普通个人且不依赖数字设备或专家的学习工具，同时覆盖发件人、链接、HTTPS、URL 和附件等钓鱼识别要点。",
    "method": "作者开发了“Hook & Match”模拟纸牌游戏，共 56 张卡片，分为两轮，每轮 28 张；玩家把绿色句子开头卡与白色句尾卡配对，翻转卡片背面形成的图案可自行核对答案。卡片内容覆盖可配置发件人名称、发件人地址的 who-area、悬停查看链接、HTTPS 不等于安全、URL 域名识别以及附件后缀等策略。研究采用前测—游戏—后测三阶段，前测和后测相隔游戏前后各两天；两次测试均让参与者随机判断 20 个来自 YouTube、Airbnb、Apple、Amazon、Lufthansa、Google、LinkedIn、Microsoft、DHL、Vodafone 和 HelloFresh 等服务的合法或钓鱼邮件示例，并测量钓鱼敏感性、判断标准和确定性。研究还收集 SeBIS、SA-6 量表和游戏感知数据，使用重复测量 ANOVA、Welch 单因素检验及回归分析回答四个研究问题。",
    "experiments": "在排除无法匹配前后测代码的 2 人和缺少两轮卡片结果的 3 人后，最终分析 62 名参与者（36 名男性、26 名女性）。钓鱼识别敏感性 d′ 从前测的 1.77 提升到后测的 2.48，重复测量 ANOVA 显示差异显著（F(1,61)=30.884，p<0.001，广义 η²G=0.142，大效应）；判断标准变化不显著（F(1,61)=1.452，p=0.233）。前测敏感性最低四分位的提升显著高于其他三组（Welch 检验 p<0.001，F(3,27)=8.96，ω²p=0.43）。确定性也从 5.18（SD=1.28）提升到 5.89（SD=1.02），差异显著（F(1,61)=19.28，p<0.001，广义 η²G=0.088，中等效应）。SeBIS 四分位组的提升差异不显著（p=0.222），SA-6 四分位组差异显著（p=0.016，F(3,30.82)=4.02，ω²p=0.21）；五项感知问题的正向回答比例为 73%（动机）至 92%（喜欢）。作者指出，游戏效果至少保持到两天，但该设计不能证明长期保持。",
    "contribution": "贡献包括：提出一种面向普通个人的模拟单人自我引导钓鱼教育游戏；用卡片背面图案和句子结构支持无专家自检与主动反思；通过相隔两天的前后测显示其对钓鱼敏感性和信心的改善，且初始敏感性最低者收益最大。局限包括样本主要为 20—30 岁且教育程度偏高，底部安全意识人群招募不足；实验室观察环境可能改变玩家行为；部分量表经过翻译，可能带来语义和语言偏差；若重复游玩，游戏的再玩性和新增学习有限；研究只观察到两天后的效果，尚未验证长期保持及更广泛人群中的可推广性。\n---\nDOI: 10.1145/3833421",
