    "method": "DiaCoG 从局部观测提取共享的一致性关系和独特的差异性关系，构造动态隐式协调图。作者给出适配集中训练分散执行（CTDE）的 DiaCoG-DE，以及适配集中训练集中执行（CTCE）的 DiaCoG-CE；信息论分析说明同时建模两类信息比只使用一致性具有更强的价值估计和动作选择表达能力，并可与 value-based MARL 结合。",
