    "contribution": "贡献是把观测一致性与差异性统一纳入协调图，提出两种 actor-critic 实现并给出信息论表达能力分析，同时验证跨 MARL 范式的适配性。局限是当前未显式处理角色异质性，实验聚焦完全合作场景；竞争或混合合作—竞争环境，以及所学隐式图更深入的理论性质仍需研究。\n---\nDOI: 10.1016/j.artint.2026.104603",
