    "summary": "本文提出面向多阶段过程的顺序因果发现方法 OCDM，把已知阶段层级用于约束因果顺序搜索，并用随机门控神经网络剪枝初始有向图，以更准确且更高效地恢复过程中的因果结构。",
    "question": "制造、信息系统和服务运营等过程通常由多个有先后关系的阶段组成，变量所属阶段往往已知，但变量之间的直接因果关系未知。通用因果发现方法如果忽略这种过程知识，可能推断出违背工艺顺序的方向，产生大量不合理候选边；当变量数和阶段数增加时，传统剪枝方法的计算成本也会迅速上升。论文关注如何在满足多阶段层级结构的前提下先得到更可靠的因果顺序，再从顺序诱导的稠密有向无环图中有效去除伪边。",
    "method": "OCDM假设观测数据遵循无潜在混杂变量的非线性加性高斯噪声模型，并假设真实图是分层有向无环图：边只能出现在同层或由上层指向下层。顺序搜索以基于得分匹配的方法为基础，利用得分函数雅可比对角元素方差识别叶节点；与普通的全局搜索不同，OCDM从最后阶段开始，只在当前阶段内比较候选叶节点，逐阶段向前完成排序，从而把阶段知识直接注入因果顺序。根据得到的顺序，方法构造顺序连接图，使每个节点连接到顺序中位于其后的节点，该图天然无环。最后，OCDM用随机门控神经网络 STG-NN 对候选父节点进行稀疏选择和剪枝，并保留门控值非零的边；论文同时报告了传统 CAM 剪枝版本，用于比较剪枝策略本身的影响。",
    "experiments": "作者在随机图模拟数据、少阶段场景、多阶段场景、含噪阶段标签和混合连续/离散变量数据上评估方法，并使用模拟的多阶段制造装配过程 causalAssembly 作为伪真实数据。因果顺序方面，OCDM在所有数据集上都取得最低或最优的拓扑顺序偏差：在三阶段、每阶段十个节点的低维场景中，平均 Dtop 为 3，比最好的竞争方法 DiffAN 低 67%；在更高维场景中，相比当时表现最好的 SCORE，Dtop 低 90%。在 AUROC、AUPRC、SHD 和 SID 等因果图指标上，OCDM整体持续优于约束型、评分型和其他顺序型基线。对于二十阶段、每阶段十个节点的 200 节点场景，STG-NN 版本约用 2.75 小时完成因果图推断，略慢于 PC 的约 2.1 小时，但得到的图明显更准确；STG-NN剪枝约需 1.2 小时，约为 CAM 剪枝 2.2 小时的一半。混合类型数据和带噪阶段信息实验也显示出一定鲁棒性，但剪枝仍可能删除部分真实边。",
    "contribution": "论文的主要贡献是把多阶段过程中的层级和顺序知识系统地融入因果顺序搜索，减少反直觉方向和无效候选边，并提出适合较高维过程数据的 STG-NN 剪枝方案。实验同时检验了顺序估计、图恢复、计算效率和偏离理想假设时的鲁棒性。局限包括：方法依赖非线性加性高斯噪声、因果充分性和已知阶段信息，存在潜在混杂时可能失效；STG-NN 与 CAM 都缺少恢复真实父集的理论保证，仍有过度剪枝；验证数据以模拟和伪真实数据为主，规模最高约 200 个变量，尚不足以代表多种真实工业过程。后续需要扩展到含潜在混杂、更多变量类型、阶段信息不完整以及更大规模真实生产数据的因果发现，并结合领域先验或集成策略降低过度剪枝。\n---\nDOI: 10.1109/TKDE.2026.3710776",
